script:
frappe.listview_settings['Allowance'] = frappe.listview_settings['Allowance'] || {};
frappe.listview_settings['Allowance'].button = {
  show: function(doc){ return true; },
  get_label: function(){ return '\uD83D\uDC41'; },
  get_description: function(doc){ return 'Quick preview of ' + doc.name; },
  action: function(doc){
    var url = '/printview?doctype=' + encodeURIComponent('Allowance') + '&name=' + encodeURIComponent(doc.name) + '&trigger_print=0&no_letterhead=0';
    var d = new frappe.ui.Dialog({ title: doc.name + '  \u2014  preview', size: 'extra-large' });
    d.$body.html('<iframe src="' + url + '" style="width:100%;height:75vh;border:0;background:#fff"></iframe>');
    d.show();
  }
};

frappe.ui.form.on('Bulk Update', {
  refresh(frm){
    setTimeout(function(){
      if (frm.page.wrapper.find('.btn-nav-home').length) return;
      frm.page.add_button(__('Home'), function(){ frappe.set_route('app','dolphin'); }).addClass('btn-nav-home');
      frm.page.add_button(__('Back'), function(){ window.history.back(); }).addClass('btn-nav-back');
    }, 600);
  }
});

frappe.ui.form.on('Buyer', {
  onload_post_render: function(frm){ dolphin_btns(); },
  refresh: function(frm){ dolphin_btns(); }
});
function dolphin_btns(){
  var st=document.getElementById('dolphin-global-btn-style');
  if(!st){ st=document.createElement('style'); st.id='dolphin-global-btn-style'; document.head.appendChild(st); }
  st.textContent=".page-actions .standard-actions .primary-action{background:#0F2540 !important;border:1px solid #D4A24A !important;color:#fff !important;}\n.page-actions .standard-actions .primary-action:hover{background:#1a3a5c !important;}\n.page-actions .custom-actions .btn, .page-actions .custom-actions .inner-group-button > .btn{background:#0F2540 !important;color:#fff !important;border:1px solid #D4A24A !important;border-radius:6px !important;margin-left:6px !important;font-weight:600 !important;}\n.page-actions .custom-actions .btn:hover, .page-actions .custom-actions .inner-group-button > .btn:hover{background:#D4A24A !important;color:#0F2540 !important;}\n.page-actions .menu-btn-group > .btn{border:1px solid #D4A24A !important;}";
}

frappe.listview_settings['Buyer'] = frappe.listview_settings['Buyer'] || {};
frappe.listview_settings['Buyer'].button = {
  show: function(doc){ return true; },
  get_label: function(){ return '\uD83D\uDC41'; },
  get_description: function(doc){ return 'Quick preview of ' + doc.name; },
  action: function(doc){
    var url = '/printview?doctype=' + encodeURIComponent('Buyer') + '&name=' + encodeURIComponent(doc.name) + '&trigger_print=0&no_letterhead=0';
    var d = new frappe.ui.Dialog({ title: doc.name + '  \u2014  preview', size: 'extra-large' });
    d.$body.html('<iframe src="' + url + '" style="width:100%;height:75vh;border:0;background:#fff"></iframe>');
    d.show();
  }
};

frappe.ui.form.on('Buyer Inspection', {
  refresh(frm){ frm.__dm=frm.__dm||{}; (frm.doc.block_rows||[]).forEach(function(r){ ['length_gross','width_gross','height_gross'].forEach(function(f){ if(r[f]!=null) frm.__dm[r.name+':'+f]=r[f]; }); }); }
});
frappe.ui.form.on('Buyer Inspection Block', {
  length_gross:function(frm,cdt,cdn){dmeasChk(frm,cdt,cdn,'length_gross');},
  width_gross:function(frm,cdt,cdn){dmeasChk(frm,cdt,cdn,'width_gross');},
  height_gross:function(frm,cdt,cdn){dmeasChk(frm,cdt,cdn,'height_gross');}
});
function dmeasChk(frm,cdt,cdn,f){ var r=locals[cdt][cdn]; var v=r[f]; frm.__dm=frm.__dm||{}; var k=cdn+':'+f; if(v===''||v===null||v===undefined) return; var n=Number(v); if(Number.isInteger(n)&&n>=10&&n<=999){ frm.__dm[k]=n; return; } frappe.show_alert({message:f.replace('_gross','').toUpperCase()+' must be a whole number between 10 and 999',indicator:'red'},6); frappe.model.set_value(cdt,cdn,f,(k in frm.__dm)?frm.__dm[k]:null); }

frappe.ui.form.on('Buyer Inspection', {
  refresh: function(frm) {
    frm.set_query('marking', function() { return { filters: { active: 1 } }; });
    frm.set_query('export_buyer', function() { return { filters: { status: 'Active' } }; });
  }
});

frappe.ui.form.on('Buyer Inspection', {
 refresh: function(frm){
  frm.add_custom_button('Add Blocks from Stock', function(){
   new frappe.ui.form.MultiSelectDialog({
    doctype:'Quarry Block', target:frm,
    setters:{ block_number:'', status:'In Stock', pit:null, granite_quality_grade:null}, columns:['block_number','status','pit'],
    add_filters_group:1,
    get_query:function(){ return { filters:{ status:'In Stock' } }; },
    action:function(selections){
     var n=0;
     (selections||[]).forEach(function(nm){
      if((frm.doc.block_rows||[]).some(function(r){return String(r.block)===String(nm);})) return;
      var row=frm.add_child('block_rows',{block:nm});
      frm.script_manager.trigger('block', row.doctype, row.name); n++;
     });
     frm.refresh_field('block_rows');
     frappe.show_alert({message:n+' in-stock block(s) added',indicator:'green'});
    }
   });
  }).addClass('btn-primary');
 }
});

frappe.ui.form.on('Buyer Inspection', {
 refresh: function(frm){
  window.__dolphinBIAdd = function(frm, tokens, done){
    tokens=(tokens||[]).map(function(t){return String(t).trim();}).filter(function(t){return t;});
    tokens=tokens.filter(function(x,i){return tokens.indexOf(x)===i;});
    if(!tokens.length){ if(done)done({msg:'No block numbers.',color:'orange'}); return; }
    frappe.call({method:'frappe.client.get_list',args:{doctype:'Quarry Block',filters:[['block_number','in',tokens]],fields:['name','block_number','status'],limit_page_length:0},callback:function(r){
      var rows=r.message||[], byNum={}; rows.forEach(function(b){var k=String(b.block_number); if(!byNum[k]||b.status==='In Stock')byNum[k]=b;});
      var already={}; (frm.doc.block_rows||[]).forEach(function(x){if(x.block)already[String(x.block)]=1;});
      var added=[],missing=[],dup=[],notstock=[],chain=Promise.resolve();
      tokens.forEach(function(t){var b=byNum[t]; if(!b){missing.push(t);return;} if(already[String(b.name)]){dup.push(t);return;} if(b.status!=='In Stock')notstock.push(t+' ('+b.status+')'); already[String(b.name)]=1; var row=frm.add_child('block_rows'); chain=chain.then(function(){return frappe.model.set_value(row.doctype,row.name,'block',b.name);}).then(function(){return frappe.model.set_value(row.doctype,row.name,'block_no',String(b.block_number));}).then(function(){return frappe.model.set_value(row.doctype,row.name,'block_number_input',String(b.block_number));}); added.push(t);});
      chain.then(function(){ frm.doc.block_rows=(frm.doc.block_rows||[]).filter(function(r){return r.block||r.block_number_input||r.block_no||r.quarry_block_no;}); frm.refresh_field('block_rows'); var msg=added.length+' block(s) added.'; if(notstock.length)msg+=' Not In Stock: '+notstock.join(', ')+'.'; if(dup.length)msg+=' Already added: '+dup.join(', ')+'.'; if(missing.length)msg+=' Not found: '+missing.join(', ')+'.'; if(done)done({msg:msg,color:(missing.length||notstock.length)?'orange':'green'}); });
    }});
  };

  if(frm.is_new() && !frm.__qiHandoffDone){
    try{ var __raw=localStorage.getItem('dolphin_bi_from_qi'); if(__raw){ localStorage.removeItem('dolphin_bi_from_qi'); frm.__qiHandoffDone=true; var __d=JSON.parse(__raw); if(__d&&__d.nums&&__d.nums.length){ setTimeout(function(){ window.__dolphinBIAdd(frm,__d.nums,function(s){ frappe.show_alert({message:'From '+(__d.qi||'QI')+': '+s.msg,indicator:s.color},8); }); },900); } } }catch(e){}
  }

  frm.add_custom_button('Add by Block No', function(){
   var d=new frappe.ui.Dialog({title:'Add Blocks by Number', fields:[{fieldname:'nums',fieldtype:'Small Text',reqd:1,label:'Block numbers',description:'Comma / space separated, e.g. 1057,1052,1020'}], primary_action_label:'Add', primary_action: function(v){
    var toks=(v.nums||'').split(/[\s,;]+/);
    window.__dolphinBIAdd(frm, toks, function(s){ d.hide(); frappe.show_alert({message:s.msg,indicator:s.color},8); });
   }});
   d.show();
  },'Add Blocks');

  frm.add_custom_button('Add from QI', function(){
   var d=new frappe.ui.Dialog({title:'Add Blocks from Quarry Inspection', size:'large', fields:[
     {fieldname:'qi',fieldtype:'Link',options:'Quarry Inspection',reqd:1,label:'Quarry Inspection (latest first)'},
     {fieldname:'pick',fieldtype:'HTML'}
   ], primary_action_label:'Add Selected', primary_action: function(){
     var sel=d.$wrapper.find('.dbi-blk:checked').map(function(){return $(this).val();}).get();
     if(!sel.length){frappe.msgprint('Select at least one block.');return;}
     window.__dolphinBIAdd(frm, sel, function(s){ d.hide(); frappe.show_alert({message:s.msg,indicator:s.color},8); });
   }});
   d.fields_dict.qi.df.onchange=function(){
     var qi=d.get_value('qi'); if(!qi){d.fields_dict.pick.$wrapper.html('');return;}
     frappe.db.get_doc('Quarry Inspection',qi).then(function(doc){
       var rows=(doc.block_rows||[]);
       var html='<div style="max-height:320px;overflow:auto"><table class="table table-bordered" style="font-size:12px"><thead><tr><th><input type="checkbox" class="dbi-all" checked></th><th>Block No</th><th>L</th><th>W</th><th>H</th><th>Vol</th></tr></thead><tbody>';
       var n=0; rows.forEach(function(r){var bn=r.quarry_block_no||''; if(!bn)return; n++; html+='<tr><td><input type="checkbox" class="dbi-blk" value="'+bn+'" checked></td><td>'+bn+'</td><td>'+(r.length_gross||'')+'</td><td>'+(r.width_gross||'')+'</td><td>'+(r.height_gross||'')+'</td><td>'+(r.gross_volume||'')+'</td></tr>';});
       html+='</tbody></table></div><div class="text-muted">'+n+' block(s) in this QI</div>';
       d.fields_dict.pick.$wrapper.html(html);
       d.$wrapper.find('.dbi-all').on('change',function(){ d.$wrapper.find('.dbi-blk').prop('checked',this.checked); });
     });
   };
   d.show();
  },'Add Blocks');
  frm.add_custom_button('Return to QI', function(){
   var grid=frm.fields_dict.block_rows.grid; var rows=((grid.get_selected_children?grid.get_selected_children():(grid.get_selected()||[]).map(function(n){return locals['Buyer Inspection Block'][n];}))||[]).filter(function(r){return r&&r.block;});
   if(!rows.length){frappe.msgprint('Tick the block(s) you want to return first.');return;}
   frappe.confirm('Set '+rows.length+' block(s) back to In Stock and unlink from this Buyer Inspection?', function(){
     var chain=Promise.resolve();
     rows.forEach(function(r){ chain=chain.then(function(){ return frappe.call({method:'frappe.client.set_value',args:{doctype:'Quarry Block',name:r.block,fieldname:{status:'In Stock',buyer_inspection:''}}}); }); });
     chain.then(function(){ var __rn=rows.map(function(x){return x.name;}); frm.doc.block_rows=(frm.doc.block_rows||[]).filter(function(x){return __rn.indexOf(x.name)<0;}); try{ if(typeof bi_recalc_all==='function') bi_recalc_all(frm); }catch(e){} frm.refresh_field('block_rows'); frm.dirty(); frappe.show_alert({message:rows.length+' block(s) returned to QI — pick new blocks',indicator:'orange'}); });
   });
  });
 }
});

frappe.ui.form.on('Buyer Inspection Block', {
  block_number_input: function(frm, cdt, cdn){
    var row=locals[cdt][cdn]; var bn=(row.block_number_input||'').toString().trim(); if(!bn) return; if(row.block) return;
    frappe.call({method:'frappe.client.get_list',args:{doctype:'Quarry Block',filters:[['block_number','=',bn]],fields:['name','block_number','status'],limit_page_length:1},callback:function(r){
      var b=(r.message||[])[0]; if(!b){frappe.show_alert({message:'Block '+bn+' not found',indicator:'orange'});return;}
      frappe.model.set_value(cdt,cdn,'block',b.name).then(function(){ frappe.model.set_value(cdt,cdn,'block_no',String(b.block_number)); if(b.status!=='In Stock')frappe.show_alert({message:'Block '+bn+' is '+b.status,indicator:'orange'}); });
    }});
  }
});

frappe.ui.form.on('Buyer Inspection', {
  refresh: function(frm){
    if(window.__dolphinEyeObs) return;
    window.__dolphinEyeObs = true;
    function colIndex(table, re){ var ths=table.querySelectorAll('thead th, thead td'); for(var i=0;i<ths.length;i++){ if(re.test((ths[i].textContent||'').trim())) return i; } return -1; }
    function preview(bno){
      frappe.db.get_list('Quarry Block',{filters:{block_number:bno},fields:['name','block_number','export_block_no','granite_quality_grade','status','length_gross','width_gross','height_gross','gross_volume'],limit:1}).then(function(r){
        var eh=frappe.utils.escape_html;
        if(!r || !r.length){ frappe.msgprint({title:'Block '+eh(bno), message:'No block details found.'}); return; }
        var b=r[0];
        var dim=(b.length_gross||'')+' x '+(b.width_gross||'')+' x '+(b.height_gross||'');
        var row=function(k,v){ return '<tr><td style="width:42%"><b>'+k+'</b></td><td>'+v+'</td></tr>'; };
        var html='<table class="table table-bordered" style="margin:0">'+row('Block number',eh(b.block_number||''))+row('Export number',eh(b.export_block_no||'-'))+row('Grade',eh(b.granite_quality_grade||''))+row('Status',eh(b.status||''))+row('Size (LxWxH)',eh(dim))+row('Gross volume',eh((b.gross_volume||'')+''))+'</table>';
        var d=new frappe.ui.Dialog({title:'Block '+(b.block_number||bno)+' preview'});
        d.$body.html(html); d.show();
      });
    }
    function inject(){
      var modal=document.querySelector('.modal.show, .modal.in'); if(!modal) return;
      var table=modal.querySelector('table'); if(!table) return;
      if(!table.querySelector('tbody input[type=checkbox]')) return;
      var bi=colIndex(table,/block/i); if(bi<0) bi=0;
      var rows=table.querySelectorAll('tbody tr');
      rows.forEach(function(tr){
        if(tr.querySelector('.dolphin-eye')) return;
        var cells=tr.querySelectorAll('td'); if(!cells.length) return;
        var bcell=cells[Math.min(bi,cells.length-1)];
        var bno=(bcell.textContent||'').trim(); if(!bno) return;
        var host=cells[0];
        var eye=document.createElement('span');
        eye.className='dolphin-eye'; eye.title='Preview block '+bno;
        eye.style.cssText='cursor:pointer;margin-left:6px;color:#185fa5;font-size:14px;vertical-align:middle;';
        eye.innerHTML='&#128065;';
        eye.addEventListener('click', function(ev){ ev.stopPropagation(); ev.preventDefault(); preview(bno); });
        host.appendChild(eye);
      });
    }
    var mo=new MutationObserver(function(){ inject(); });
    if(document.body) mo.observe(document.body,{childList:true,subtree:true});
    setInterval(inject, 800);
  }
});

frappe.ui.form.on('Buyer Inspection Block', {
  block(frm, cdt, cdn){
    const row=locals[cdt][cdn];
    if(!row.block) return;
    frappe.db.get_value('Quarry Block', row.block, ['status','buyer_inspection','block_number']).then(r=>{
      const d=(r&&r.message)||{};
      if(d.status && d.status!=='In Stock'){
        const sameDoc = d.buyer_inspection && (d.buyer_inspection===frm.doc.name);
        if(!sameDoc){
          const where = d.buyer_inspection ? (' on '+d.buyer_inspection) : '';
          frappe.msgprint({title:'Block not available', indicator:'orange', message:'Block <b>'+(d.block_number||row.block)+'</b> is currently <b>'+d.status+'</b>'+where+'. It may already be committed elsewhere.'});
        }
      }
    });
  }
});

frappe.ui.form.on('Buyer Inspection', {
  refresh: function(frm){ dolphin_status_bi(frm); },
  block_rows_add: function(frm){ dolphin_status_bi(frm); }
});
function dolphin_status_bi(frm){
  var rows = frm.doc.block_rows || [];
  var blocks = rows.map(function(r){ return r.block; }).filter(Boolean);
  if(!blocks.length){ return; }
  frappe.db.get_list('Quarry Block', {filters:{name:['in',blocks]}, fields:['name','status'], limit:0}).then(function(recs){
    var m = {}; (recs||[]).forEach(function(x){ m[x.name]=x.status; });
    rows.forEach(function(row){ row.dolphin_avail = m[row.block] || ''; });
    if(frm.fields_dict.block_rows){ frm.fields_dict.block_rows.grid.refresh(); }
  });
}

(function(){
var SC={'In Stock':['#eaf3de','#3b6d11'],'Buyer Marked':['#faeeda','#854f0b'],'In Delivery Challan':['#e6f1fb','#0c447c'],'Dispatched/Transported':['#e6f1fb','#0c447c'],'At Port':['#eeedfe','#3c3489'],'At Bannikoppa Station yard':['#eeedfe','#3c3489'],'Shipped':['#e1f5ee','#0f6e56'],'Sold':['#f1efe8','#444441']};
var RANK={'In Stock':0,'Buyer Marked':1,'In Delivery Challan':2,'Dispatched/Transported':3,'At Port':4,'At Bannikoppa Station yard':4,'Shipped':5,'Sold':6};
var FL=['name','block_number','export_block_no','status','delivery_challan','buyer_inspection','source_quarry_inspection','granite_quality_grade','length_gross','width_gross','height_gross','gross_volume'];
function esc(s){return frappe.utils.escape_html(s==null?'':(''+s));}
function pdf(dt,nm,fmt){return '/api/method/frappe.utils.print_format.download_pdf?doctype='+encodeURIComponent(dt)+'&name='+encodeURIComponent(nm)+'&format='+encodeURIComponent(fmt)+'&no_letterhead=0';}
function eye(dt,nm,fmt){return nm?' <a href="'+pdf(dt,nm,fmt)+'" target="_blank" style="font-size:11px;border:1px solid #185fa5;color:#185fa5;border-radius:10px;padding:1px 8px;text-decoration:none;margin-left:6px">&#128065; PDF</a>':'';}
function journeyHTML(b){
 var sc=SC[b.status]||['#f1efe8','#444441']; var rank=(b.status in RANK)?RANK[b.status]:0;
 var steps=[
  {l:'Quarried',v:b.block_number||b.name,done:true},
  {l:'Quarry Inspection',v:b.source_quarry_inspection||'not yet',done:!!b.source_quarry_inspection,e:eye('Quarry Inspection',b.source_quarry_inspection,'Quarry Inspection - Report')},
  {l:'Buyer Inspection',v:b.buyer_inspection||'not yet',done:!!b.buyer_inspection,e:eye('Buyer Inspection',b.buyer_inspection,'Buyer Inspection - Report')},
  {l:'Delivery Challan',v:b.delivery_challan||'not yet',done:!!b.delivery_challan,e:eye('Delivery Challan',b.delivery_challan,'Dolphin Delivery Challan')},
  {l:'Transported',v:(rank>=3?(b.export_block_no||'yes'):'not yet'),done:rank>=3},
  {l:'At Port',v:(rank>=4?(b.export_block_no||'yes'):'not yet'),done:rank>=4},
  {l:'Shipped',v:(rank>=5?(b.export_block_no||'yes'):'not yet'),done:rank>=5}
 ];
 var head='<div style="margin-bottom:10px">Current status: <b style="background:'+sc[0]+';color:'+sc[1]+';padding:2px 12px;border-radius:12px">'+esc(b.status||'')+'</b></div>';
 var body=steps.map(function(s,i){var cur=(!s.done && i>0 && steps[i-1].done);var col=s.done?'#0f6e56':(cur?'#b8860b':'#c2c8d0');var dot=s.done?'&#9679;':(cur?'&#9673;':'&#9675;');return '<div style="display:flex;gap:12px;align-items:flex-start;padding:7px 0;border-bottom:1px solid #f2f4f7"><span style="color:'+col+';font-size:17px;line-height:1">'+dot+'</span><div><div style="font-size:10.5px;text-transform:uppercase;letter-spacing:.03em;color:#8a929c">'+s.l+'</div><div style="font-weight:600;color:'+(s.done?'#1f2a3a':(cur?'#7a5a00':'#aab1ba'))+'">'+esc(''+s.v)+(s.e||'')+'</div></div></div>';}).join('');
 return '<div style="font-family:inherit">'+head+body+'</div>';
}
window.dolphin_open_journey=window.dolphin_open_journey||function(bno){
 if(!bno){frappe.msgprint('No block number on this row.');return;}
 function q(f){return frappe.call({method:'frappe.client.get_list',args:{doctype:'Quarry Block',filters:f,fields:FL,limit_page_length:5}}).then(function(r){return r.message||[];});}
 q([['block_number','=',bno]]).then(function(bl){return bl.length?bl:q([['name','=',bno]]);}).then(function(bl){return bl.length?bl:q([['export_block_no','=',bno]]);}).then(function(bl){
   if(!bl.length){frappe.msgprint('Block '+esc(bno)+' not found in stock records.');return;}
   var b=bl[0]; var d=new frappe.ui.Dialog({title:'Block '+esc(b.block_number||b.name)+' \u2014 journey',fields:[{fieldtype:'HTML',fieldname:'j'}]});
   d.fields_dict.j.$wrapper.html(journeyHTML(b)); d.show();
 });
};
function strip(frm,bf){
 $(frm.wrapper).find('#dolphin-status-strip').remove();
 var nums=(frm.doc.block_rows||[]).map(function(r){return r[bf];}).filter(Boolean);
 if(!nums.length) return;
 frappe.call({method:'frappe.client.get_list',args:{doctype:'Quarry Block',filters:[['block_number','in',nums]],fields:['block_number','status'],limit_page_length:0}}).then(function(r){
  var rows=r.message||[]; var counts={}; rows.forEach(function(x){counts[x.status]=(counts[x.status]||0)+1;});
  var order=['In Stock','Buyer Marked','In Delivery Challan','Dispatched/Transported','At Port','At Bannikoppa Station yard','Shipped','Sold'];
  var keys=Object.keys(counts).sort(function(a,b){var ia=order.indexOf(a),ib=order.indexOf(b);return (ia<0?99:ia)-(ib<0?99:ib);});
  var chips=keys.map(function(s){var c=SC[s]||['#eee','#333'];return '<span style="background:'+c[0]+';color:'+c[1]+';padding:3px 11px;border-radius:12px;font-weight:600;font-size:12px;margin:0 6px 4px 0;display:inline-block">'+esc(s)+' &middot; '+counts[s]+'</span>';}).join('');
  var total=nums.length, found=rows.length;
  var html='<div id="dolphin-status-strip" style="background:#f7f9fc;border:1px solid #e5e7eb;border-left:4px solid #16304F;border-radius:8px;padding:10px 14px;margin:6px 0 4px"><span style="font-weight:700;color:#16304F;margin-right:10px">Blocks \u2014 where they are now ('+total+'):</span>'+chips+(found<total?'<span style="color:#98a2b3;font-size:11px">'+(total-found)+' not tracked</span>':'')+'</div>';
  var $sec=$(frm.fields_dict.block_rows.wrapper).closest('.form-section');
  if($sec.length) $sec.before(html); else $(frm.layout.wrapper).prepend(html);
 });
}
