function bi_calc_row(frm, cdt, cdn){
    let row=locals[cdt][cdn];
    let l=row.length_gross||0,w=row.width_gross||0,h=row.height_gross||0;
    let factor=row.specific_gravity||frm.doc.tonnage_factor||0;
    let gv=Math.round(l*w*h/1000000*100)/100;
    frappe.model.set_value(cdt,cdn,'gross_volume',gv);
    frappe.model.set_value(cdt,cdn,'gross_tonnage',Math.round(gv*factor*100)/100);
    if(frm.doc.show_net_calculations && frm.doc.allowance_cm){
        let a=frm.doc.allowance_cm;
        if(l>a && w>a && h>a){
            let nl=l-a,nw=w-a,nh=h-a,nv=Math.round(nl*nw*nh/1000000*100)/100;
            frappe.model.set_value(cdt,cdn,'net_length',nl);
            frappe.model.set_value(cdt,cdn,'net_width',nw);
            frappe.model.set_value(cdt,cdn,'net_height',nh);
            frappe.model.set_value(cdt,cdn,'net_volume',nv);
            frappe.model.set_value(cdt,cdn,'net_tonnage',Math.round(nv*factor*100)/100);
        } else {
            ['net_length','net_width','net_height','net_volume','net_tonnage'].forEach(f=>frappe.model.set_value(cdt,cdn,f,0));
        }
    } else {
        ['net_length','net_width','net_height','net_volume','net_tonnage'].forEach(f=>frappe.model.set_value(cdt,cdn,f,0));
    }
    bi_totals(frm);
}
function bi_totals(frm){
    let gv=0,gt=0,nv=0,nt=0,n=0;
    (frm.doc.block_rows||[]).forEach(r=>{gv+=r.gross_volume||0;gt+=r.gross_tonnage||0;nv+=r.net_volume||0;nt+=r.net_tonnage||0;n++;});
    frm.set_value('total_gross_volume',Math.round(gv*100)/100);
    frm.set_value('total_gross_tonnage',Math.round(gt*100)/100);
    frm.set_value('total_net_volume',Math.round(nv*100)/100);
    frm.set_value('total_net_tonnage',Math.round(nt*100)/100);
    frm.set_value('block_count',n);
}
function bi_recalc_all(frm){ (frm.doc.block_rows||[]).forEach(r=>bi_calc_row(frm,r.doctype,r.name)); }
