function dolphin_paint_loading(frm){
  var rows=(frm.doc.block_rows||[]);
  var ids=rows.map(function(r){return r.block;}).filter(Boolean);
  if(!ids.length){return;}
  frappe.db.get_list('Quarry Block',{filters:[['name','in',ids]],fields:['name','status'],limit:0}).then(function(recs){
    var smap={}; recs.forEach(function(x){smap[x.name]=x.status;});
    frm.__dolphin_smap=smap;
    var PENDING=['In Stock','Buyer Marked'];
    var pend=0,done=0;
    rows.forEach(function(r){var st=smap[r.block]||''; if(PENDING.indexOf(st)>=0){pend++;}else{done++;}});
    var grid=frm.fields_dict.block_rows.grid; var $w=grid.wrapper;
    var html='<div id="dolphin-loading-summary" style="margin:6px 0;font-size:12px;">'+
      '<b>Loading status:</b> '+
      '<span style="background:#E4F4E8;color:#256b36;padding:2px 8px;border-radius:10px;margin-right:6px;">Transported / loaded: '+done+'</span>'+
      '<span style="background:#FFF3D6;color:#8a6d1a;padding:2px 8px;border-radius:10px;">Pending to transport: '+pend+'</span></div>';
    $w.find('#dolphin-loading-summary').remove(); $w.prepend(html);
    dolphin_color_rows(frm);
    if(!frm.__dolphin_obs){
      var target=$w.find('.grid-body')[0]||$w[0];
      frm.__dolphin_obs=new MutationObserver(function(){dolphin_color_rows(frm);});
      frm.__dolphin_obs.observe(target,{childList:true,subtree:true});
    }
  });
}
function dolphin_color_rows(frm){
  var smap=frm.__dolphin_smap; if(!smap){return;}
  var PENDING=['In Stock','Buyer Marked'];
  var grid=frm.fields_dict.block_rows.grid;
  (grid.grid_rows||[]).forEach(function(gr){
    if(!gr.row){return;}
    var st=smap[gr.doc.block]||'';
    if(PENDING.indexOf(st)>=0){
      gr.row.css({'background-color':'#25D366','color':'#04361b','opacity':'1'});
      gr.row.children('.col').css({'background-color':'#25D366','color':'#04361b'});
    } else {
      gr.row.css({'background-color':'','color':'','opacity':'0.45'});
      gr.row.children('.col').css({'background-color':'','color':''});
    }
  });
}

let _dolphinTol = null;
async function _getTol() {
  if (_dolphinTol) return _dolphinTol;
  try {
    const d = await frappe.db.get_doc('Inspection Tolerance Settings');
    _dolphinTol = {l:d.length_tol_cm||5, w:d.width_tol_cm||5, h:d.height_tol_cm||5, v:d.volume_tol_pct||5};
  } catch(e){ _dolphinTol = {l:5,w:5,h:5,v:5}; }
  return _dolphinTol;
}
async function _computeRow(cdt, cdn) {
  const row = locals[cdt][cdn];
  if (!row) return;
  const tol = await _getTol();
  const dl = (row.q_length_gross||0) - (row.length_gross||0);
  const dw = (row.q_width_gross||0) - (row.width_gross||0);
  const dh = (row.q_height_gross||0) - (row.height_gross||0);
  const _qv = ((row.q_length_gross||0)*(row.q_width_gross||0)*(row.q_height_gross||0)/1e6) || (row.q_gross_volume||0); const _ov = ((row.length_gross||0)*(row.width_gross||0)*(row.height_gross||0)/1e6) || (row.gross_volume||0); const dv = _qv ? ((_qv - _ov) / _qv * 100) : 0;
  frappe.model.set_value(cdt, cdn, 'diff_length', dl);
  frappe.model.set_value(cdt, cdn, 'diff_width', dw);
  frappe.model.set_value(cdt, cdn, 'diff_height', dh);
  frappe.model.set_value(cdt, cdn, 'diff_volume_pct', Math.round(dv*100)/100);
  const over = Math.abs(dl)>tol.l || Math.abs(dw)>tol.w || Math.abs(dh)>tol.h || Math.abs(dv)>tol.v;
  frappe.model.set_value(cdt, cdn, 'variance_flag', over ? '⚠ Check' : 'OK');
}
async function _fetchAndCompute(cdt, cdn) {
  const row = locals[cdt][cdn];
  if (!row || !row.block) return;
  try {
    const r = await frappe.db.get_value('Quarry Block', row.block, ['length_gross','width_gross','height_gross','gross_volume']);
    if (r && r.message) {
      frappe.model.set_value(cdt, cdn, 'q_length_gross', r.message.length_gross);
      frappe.model.set_value(cdt, cdn, 'q_width_gross', r.message.width_gross);
      frappe.model.set_value(cdt, cdn, 'q_height_gross', r.message.height_gross);
      frappe.model.set_value(cdt, cdn, 'q_gross_volume', r.message.gross_volume);
    }
  } catch(e){}
  await _computeRow(cdt, cdn);
}
function _computeAll(frm) {
  (frm.doc.block_rows||[]).forEach(r => _computeRow(r.doctype, r.name));
  _summary(frm);
}
function _summary(frm) {
  const flagged = (frm.doc.block_rows||[]).filter(r => r.variance_flag && r.variance_flag.indexOf('Check')>=0);
  if (flagged.length) {
    const blocks = flagged.map(r => r.block || r.export_block_no || '?').join(', ');
    frm.dashboard.clear_headline();
    frm.dashboard.set_headline('⚠ ' + flagged.length + ' block(s) exceed measurement tolerance: ' + blocks, 'orange');
  } else {
    frm.dashboard.clear_headline();
  }
}
frappe.ui.form.on('Buyer Inspection', {
  refresh(frm) { setTimeout(()=>_computeAll(frm), 400); },
  validate(frm) { _computeAll(frm); }
});
frappe.ui.form.on('Buyer Inspection Block', {
  block(frm, cdt, cdn) { _fetchAndCompute(cdt, cdn).then(()=>_summary(frm)); },
  length_gross(frm, cdt, cdn) { _computeRow(cdt, cdn).then(()=>_summary(frm)); },
  width_gross(frm, cdt, cdn) { _computeRow(cdt, cdn).then(()=>_summary(frm)); },
  height_gross(frm, cdt, cdn) { _computeRow(cdt, cdn).then(()=>_summary(frm)); },
  gross_volume(frm, cdt, cdn) { _computeRow(cdt, cdn).then(()=>_summary(frm)); }
});

