frappe.ui.form.on('Buyer Inspection Block', {
  block_number_input: function(frm, cdt, cdn){
    var row = locals[cdt][cdn];
    var inp = (row.block_number_input || '').toString().trim();
    if(!inp) return;
    var FL=['block','block_no','export_block_no','length_gross','width_gross','height_gross','gross_volume','net_volume','net_tonnage'];
    function doClear(keepInput){ FL.forEach(function(f){ frappe.model.set_value(cdt,cdn,f,''); }); if(!keepInput){ frappe.model.set_value(cdt,cdn,'block_number_input',''); } frm.refresh_field('block_rows'); }
    function reject(msg){ doClear(false); setTimeout(function(){ doClear(false); }, 350); setTimeout(function(){ doClear(false); }, 700); frappe.show_alert({message:msg+' Field cleared — enter another number.', indicator:'orange'}, 6); }
    frappe.call({method:'frappe.client.get_list', args:{
      doctype:'Quarry Block',
      or_filters:[['block_number','=',inp],['export_block_no','=',inp]],
      fields:['name','block_number','export_block_no','status','length_gross','width_gross','height_gross','gross_volume'],
      limit_page_length:5
