      var rows = r.message || [];
      if(!rows.length){ reject('No block found for "'+inp+'".'); return; }
      var a=rows.filter(function(x){return String(x.block_number)===inp;})[0];
      var e=rows.filter(function(x){return String(x.export_block_no)===inp;})[0];
      var b=a||e; var matchedBy=a?'Quarry No':'Export No';
      var dup=(frm.doc.block_rows||[]).some(function(x){ return x.name!==cdn && String(x.block)===String(b.name); });
      if(dup){ reject('Block '+b.block_number+' already added.'); return; }
      if(b.status!=='In Stock'){ reject(b.block_number+' is '+b.status+', not free stock.'); return; }
      frappe.model.set_value(cdt,cdn,'block',b.name);
      frappe.model.set_value(cdt,cdn,'block_no',b.block_number);
      frappe.model.set_value(cdt,cdn,'export_block_no',b.export_block_no||'');
      frappe.model.set_value(cdt,cdn,'length_gross',b.length_gross);
      frappe.model.set_value(cdt,cdn,'width_gross',b.width_gross);
      frappe.model.set_value(cdt,cdn,'height_gross',b.height_gross);
      frappe.model.set_value(cdt,cdn,'gross_volume',b.gross_volume);
      frm.refresh_field('block_rows');
      setTimeout(function(){ try{ frm.script_manager.trigger('block',cdt,cdn); frm.refresh_field('block_rows'); }catch(e){} }, 200);
      frappe.show_alert({message:'Matched '+inp+' ('+matchedBy+') → Quarry block '+b.block_number+', '+b.status+'.', indicator:'green'}, 5);
    }});
  }
});

