    if(kept.length !== rows.length){ frm.doc.block_rows = kept; frm.refresh_field('block_rows'); }
    // flag rows with input/data but no resolved block
    var bad=[], seen={}, dup=[];
    kept.forEach(function(r, i){
      if(!r.block){ bad.push('Row '+(i+1)+(r.block_number_input ? (' \u2014 "'+r.block_number_input+'"') : '')); return; }
      if(seen[r.block]){ dup.push(r.block_no || r.block); } seen[r.block]=1;
    });
    if(bad.length){ frappe.throw({title:'Unresolved block rows', message:'These rows have no valid block. Enter a Quarry/Export number that resolves, or remove the row:<br><b>'+bad.join('<br>')+'</b>'}); }
