frappe.ui.form.on('Buyer Inspection Block', {
  async block(frm, cdt, cdn) {
    const row = frappe.get_doc(cdt, cdn);
    if (!row.block) return;

    // Fetch Quarry Block with source QI data
    try {
      const qb = await frappe.call({
        method: 'frappe.client.get',
        args: { doctype: 'Quarry Block', name: row.block },
        async: true
      });

      const block_data = qb.message;
      const qi_length = block_data.length_gross || null;
      const qi_width = block_data.width_gross || null;
      const qi_height = block_data.height_gross || null;

      // Tolerance (5 cm default)
      const tolerance_cm = 5;
      const issues = [];

      if (qi_length && row.length_gross) {
        const diff = Math.abs(qi_length - row.length_gross);
        if (diff > tolerance_cm) {
          issues.push('Length: QI=' + qi_length + ' cm, BI=' + row.length_gross + ' cm (diff=' + diff.toFixed(1) + ' cm)');
        }
      }

      if (qi_width && row.width_gross) {
        const diff = Math.abs(qi_width - row.width_gross);
        if (diff > tolerance_cm) {
          issues.push('Width: QI=' + qi_width + ' cm, BI=' + row.width_gross + ' cm (diff=' + diff.toFixed(1) + ' cm)');
        }
      }

      if (qi_height && row.height_gross) {
        const diff = Math.abs(qi_height - row.height_gross);
        if (diff > tolerance_cm) {
          issues.push('Height: QI=' + qi_height + ' cm, BI=' + row.height_gross + ' cm (diff=' + diff.toFixed(1) + ' cm)');
        }
      }

      if (issues.length > 0) {
        const msg = '⚠️ Measurement Variance for Block ' + row.block + ':\n' + issues.join('\n');
        frappe.msgprint({title: 'Measurement Alert', message: msg, indicator: 'orange'});
      } else if (qi_length && qi_width && qi_height) {
        frappe.show_alert({message: '✓ Block ' + row.block + ' measurements verified', indicator: 'green'});
      }
    } catch(e) {
      console.log('Variance check error:', e);
    }
  },

  async length_gross(frm, cdt, cdn) {
    // Trigger variance check when user manually enters length
    frappe.ui.form.trigger(cdt, cdn, 'block');
  },

  async width_gross(frm, cdt, cdn) {
    frappe.ui.form.trigger(cdt, cdn, 'block');
  },

  async height_gross(frm, cdt, cdn) {
    frappe.ui.form.trigger(cdt, cdn, 'block');
  }
});

