          label:'Block numbers', description:'Comma, space or newline separated. e.g. 601,602,603,604,605'}],
        primary_action_label: 'Add',
        primary_action: function(values){
          var tokens = (values.nums||'').split(/[\s,;]+/).map(function(s){return s.trim();}).filter(function(s){return s.length;});
          tokens = tokens.filter(function(v,i){return tokens.indexOf(v)===i;});
          if(!tokens.length){ d.hide(); return; }
          frappe.call({method:'frappe.client.get_list', args:{
            doctype:'Quarry Block',
            filters:[['block_number','in',tokens]],
            fields:['name','block_number','status','length_gross','width_gross','height_gross','gross_volume','gross_tonnage'],
            limit_page_length:0
          }, callback:function(r){
            var rows=r.message||[], byNum={};
            rows.forEach(function(b){ var k=String(b.block_number); if(!byNum[k] || b.status==='In Stock'){ byNum[k]=b; } });
            var already={}; (frm.doc.dc_block_rows||[]).forEach(function(x){ if(x.block) already[String(x.block)]=1; });
            var added=[], missing=[], notstock=[], dup=[];
            tokens.forEach(function(t){
              var b=byNum[t];
              if(!b){ missing.push(t); return; }
              if(already[String(b.name)]){ dup.push(t); return; }
              if(b.status!=='In Stock'){ notstock.push(t+' ('+b.status+')'); }
              var row=frm.add_child('dc_block_rows');
              row.block=b.name; row.block_no=b.block_number; row.length_gross=b.length_gross; row.width_gross=b.width_gross;
              row.height_gross=b.height_gross; row.gross_volume=b.gross_volume; row.gross_tonnage=b.gross_tonnage;
              already[String(b.name)]=1; added.push(t);
            });
            frm.doc.dc_block_rows=(frm.doc.dc_block_rows||[]).filter(function(x){return x.block;});frm.doc.dc_block_rows.forEach(function(x,i){x.idx=i+1;});frm.refresh_field('dc_block_rows');
            var tv=0,tt=0,n=(frm.doc.dc_block_rows||[]).length;
            (frm.doc.dc_block_rows||[]).forEach(function(x){ tv+=x.gross_volume||0; tt+=x.gross_tonnage||0; });
            tv=Math.round(tv*100)/100; tt=Math.round(tt*100)/100;
            frm.set_value('auto_total_volume',tv); frm.set_value('auto_total_tonnage',tt); frm.set_value('block_count',n);
            if(!frm.doc.allow_total_override){ frm.set_value('total_volume',tv); frm.set_value('total_tonnage',tt); }
            frm.set_value('total_amount', Math.round(((frm.doc.rate_per_mt||0)*(frm.doc.total_tonnage||0))*100)/100);
            d.hide();
            var msg = added.length+' block(s) added.';
            if(notstock.length) msg+=' Not In Stock: '+notstock.join(', ')+'.';
            if(dup.length) msg+=' Already on DC: '+dup.join(', ')+'.';
            if(missing.length) msg+=' Not found: '+missing.join(', ')+'.';
            frappe.show_alert({message:msg, indicator:(missing.length||notstock.length)?'orange':'green'}, 8);
            if(n>12) frappe.msgprint('A Delivery Challan allows max 12 blocks (currently '+n+'). Remove extras before saving.');
          }});
        }
      });
      d.show();setTimeout(function(){try{d.fields_dict.nums.$input.focus();}catch(e){}},200);
    }, 'Add Blocks');
  }
});

