            fields:['name','block_number','export_block_no','status','length_gross','width_gross','height_gross','gross_volume','gross_tonnage'],
            limit_page_length:0
          }, callback:function(r){
            var rows = r.message||[], byExp={};
            rows.forEach(function(b){ var k=String(b.export_block_no); if(!byExp[k] || b.status==='In Stock'){ byExp[k]=b; } });
            var already={}; (frm.doc.dc_block_rows||[]).forEach(function(x){ if(x.block) already[String(x.block)]=1; });
            var added=[], missing=[], dup=[], notstock=[];
            tokens.forEach(function(t){
              var b = byExp[t];
              if(!b){ missing.push(t); return; }
              if(already[String(b.name)]){ dup.push(t); return; }
              if(b.status!=='In Stock'){ notstock.push(t+' ('+b.status+')'); }
              var row = frm.add_child('dc_block_rows');
              row.block=b.name; row.block_no=b.block_number; row.export_block_no=b.export_block_no;
              row.length_gross=b.length_gross; row.width_gross=b.width_gross; row.height_gross=b.height_gross;
              row.gross_volume=b.gross_volume; row.gross_tonnage=b.gross_tonnage;
              added.push(t);
            });
            frm.refresh_field('dc_block_rows');
            var tv=0, tt=0;
            (frm.doc.dc_block_rows||[]).forEach(function(x){ tv+=(x.gross_volume||0); tt+=(x.gross_tonnage||0); });
            if(!frm.doc.allow_total_override){ frm.set_value('total_volume', tv); frm.set_value('total_tonnage', tt); }
            frm.set_value('total_amount', Math.round(((frm.doc.rate_per_mt||0)*(frm.doc.total_tonnage||0))*100)/100);
            d.hide();
            var msg = added.length+' block(s) added by export no.';
            if(notstock.length) msg += ' Not In Stock: '+notstock.join(', ')+'.';
            if(dup.length) msg += ' Already added: '+dup.join(', ')+'.';
            if(missing.length) msg += ' Export No not found: '+missing.join(', ')+'.';
            frappe.show_alert({message:msg, indicator: added.length? 'green':'orange'}, 8);
          }});
        }
      });
      d.show();
    }, 'Add Blocks');
  }
});

frappe.ui.form.on('Delivery Challan', {
