    function colIndex(table, re){ var ths=table.querySelectorAll('thead th, thead td'); for(var i=0;i<ths.length;i++){ if(re.test((ths[i].textContent||'').trim())) return i; } return -1; }
    function preview(bno){
      frappe.db.get_list('Quarry Block',{filters:{block_number:bno},fields:['name','block_number','export_block_no','granite_quality_grade','status','length_gross','width_gross','height_gross','gross_volume'],limit:1}).then(function(r){
