window.dolphin_pick_addcand = function(d, c){
  c.block = String(c.block);
  if(d._used[c.block]) return false;
  if(d._cand.some(function(x){return String(x.block)===c.block;})) return false;
  c._sel = true; d._cand.push(c); return true;
};

window.dolphin_pick_load_bi = function(d, bi){
  frappe.db.get_doc('Buyer Inspection', bi).then(function(doc){
    var rows=(doc.block_rows||[]);
    var ids=rows.map(function(r){return r.block;}).filter(Boolean);
    var expMap={}; rows.forEach(function(r){ if(r.block) expMap[String(r.block)] = r.export_block_no || r.block_no || ''; });
    if(!ids.length){ dolphin_pick_render(d); return; }
    frappe.call({method:'frappe.client.get_list', args:{doctype:'Quarry Block', filters:[['name','in',ids]], fields:['name','block_number','granite_quality_grade','granite_size_category','tonnage_factor','length_gross','width_gross','height_gross','gross_volume','gross_tonnage','buyer_inspection'], limit_page_length:0}})
    .then(function(r){
      (r.message||[]).forEach(function(b){
        dolphin_pick_addcand(d, {block:b.name, block_no: expMap[String(b.name)] || b.block_number, grade:b.granite_quality_grade||'', size:b.granite_size_category||'', sg:b.tonnage_factor||0, l:b.length_gross, w:b.width_gross, h:b.height_gross, vol:b.gross_volume||0, ton:b.gross_tonnage||0, source_bi: bi});
      });
      dolphin_pick_render(d);
    });
  });
};

window.dolphin_pick_paste = function(d){
  var raw = (d.get_value('paste')||'').split(/[\s,;]+/).map(function(s){return s.trim();}).filter(Boolean);
  if(!raw.length) return;
  frappe.call({method:'frappe.client.get_list', args:{doctype:'Quarry Block', filters:[['block_number','in',raw]],
    fields:['name','block_number','granite_quality_grade','granite_size_category','tonnage_factor','length_gross','width_gross','height_gross','gross_volume','gross_tonnage','buyer_inspection'], limit_page_length:0}})
  .then(function(r){
    var added=0, skipped=0;
    (r.message||[]).forEach(function(b){
      var ok = dolphin_pick_addcand(d, {block:b.name, block_no:b.block_number, grade:b.granite_quality_grade||'', size:b.granite_size_category||'', sg:b.tonnage_factor||0, l:b.length_gross, w:b.width_gross, h:b.height_gross, vol:b.gross_volume||0, ton:b.gross_tonnage||0, source_bi:b.buyer_inspection||''});
      if(ok) added++; else skipped++;
    });
    frappe.show_alert({message: added+' added, '+skipped+' skipped (already used/duplicate)', indicator: added?'green':'orange'});
    dolphin_pick_render(d);
  });
};

window.dolphin_pick_render = function(d){
  var rows = d._cand;
  var h = '<div style="max-height:42vh;overflow:auto"><table class="table table-bordered" style="font-size:12px;margin:0"><thead><tr>'+
    '<th><input type="checkbox" id="pk_all" checked></th><th>Block No</th><th>Grade</th><th>Size</th><th>SG</th><th>Vol</th><th>Ton</th><th>Source BI</th><th></th></tr></thead><tbody>';
  if(!rows.length){ h += '<tr><td colspan="9" style="text-align:center;color:#999;padding:14px">Pick a Buyer Inspection or paste block numbers above.</td></tr>'; }
  rows.forEach(function(b,i){
    h += '<tr><td><input type="checkbox" class="pk_row" data-i="'+i+'" '+(b._sel?'checked':'')+'></td>'+
      '<td>'+(b.block_no||'')+'</td><td>'+(b.grade||'')+'</td><td>'+(b.size||'')+'</td><td>'+(b.sg||'')+'</td>'+
      '<td>'+(b.vol||'')+'</td><td>'+(b.ton||'')+'</td><td style="color:#5a7">'+(b.source_bi||'')+'</td>'+
      '<td><span class="pk_del" data-i="'+i+'" style="cursor:pointer;color:#c33">&times;</span></td></tr>';
  });
  h += '</tbody></table></div>';
  d.fields_dict.tbl.$wrapper.html(h);
  d.fields_dict.tbl.$wrapper.find('.pk_row').on('change', function(){ d._cand[parseInt($(this).attr('data-i'))]._sel = this.checked; dolphin_pick_totals(d); });
  d.fields_dict.tbl.$wrapper.find('#pk_all').on('change', function(){ var c=this.checked; d._cand.forEach(function(x){x._sel=c;}); dolphin_pick_render(d); });
  d.fields_dict.tbl.$wrapper.find('.pk_del').on('click', function(){ d._cand.splice(parseInt($(this).attr('data-i')),1); dolphin_pick_render(d); });
  dolphin_pick_totals(d);
};

window.dolphin_pick_totals = function(d){
  var n=0, vol=0, ton=0;
  d._cand.forEach(function(b){ if(b._sel){ n++; vol+=flt(b.vol); ton+=flt(b.ton); } });
  var max = flt(d.get_value('max_ton'));
  var over = max>0 && ton>max;
  var h = '<div style="display:flex;gap:18px;align-items:center;padding:8px 4px;font-size:13px">'+
    '<span><b>'+n+'</b> selected</span>'+
    '<span>Volume <b>'+vol.toFixed(3)+'</b></span>'+
    '<span style="'+(over?'color:#c0392b;font-weight:600':'')+'">Tonnage <b>'+ton.toFixed(2)+'</b>'+(max>0?(' / '+max.toFixed(2)+(over?'  ⚠ over':'')):'')+'</span>'+
    '</div>';
  d.fields_dict.totals.$wrapper.html(h);
};

window.dolphin_pick_commit = function(frm, d){
  var added=0;
  d._cand.forEach(function(b){
    if(!b._sel) return;
    var row = frm.add_child('dc_block_rows');
    row.block=b.block; row.block_no=b.block_no; row.grade=b.grade; row.source_inspection=b.source_bi;
    row.tonnage_factor=b.sg; row.length_gross=b.l; row.width_gross=b.w; row.height_gross=b.h;
    row.gross_volume=b.vol; row.gross_tonnage=b.ton;
    added++;
  });
  frm.refresh_field('dc_block_rows');
  frappe.show_alert({message: added+' block(s) added', indicator:'green'});
  d.hide();
};

