function dolphin_dim_one(modal){
  var tbl = modal.querySelector('table'); if(!tbl) return;
  var heads = [].slice.call(tbl.querySelectorAll('thead th, thead td'));
  var bi = -1; heads.forEach(function(h,idx){ if(/block\s*no/i.test(h.textContent||'')) bi = idx; });
  if(bi < 0) return;
  if(!tbl.querySelector('tbody input[type=checkbox]')) return;
  var rows = [].slice.call(tbl.querySelectorAll('tbody tr'));
  var blocks = [];
  rows.forEach(function(r){
    var cell=r.children[bi]; if(!cell) return;
    var bn=r.getAttribute('data-dblk');
    if(!bn){ bn=(cell.textContent||'').trim(); if(bn && /\d/.test(bn) && !/pick a buyer/i.test(bn)){ r.setAttribute('data-dblk', bn);} else return; }
    blocks.push(bn);
  });
  if(!blocks.length) return;
  var key = blocks.join(','); if(tbl.__dolphin_key === key) return; tbl.__dolphin_key = key;
  frappe.call({ method:'dolphin_theme.api_arrivals.block_availability', args:{ blocks:blocks }, callback:function(res){
    var m=(res&&res.message)||{};
    rows.forEach(function(r){
      var bn=r.getAttribute('data-dblk'); if(!bn) return;
      var cell=r.children[bi]; if(!cell) return;
      var old=cell.querySelector('.dolphin-avail'); if(old) old.remove();
      var badge=document.createElement('span'); badge.className='dolphin-avail';
      badge.style.cssText='margin-left:8px;font-size:11px;font-weight:600;padding:1px 7px;border-radius:9px;white-space:nowrap;display:inline-block;';
      var v=m[bn];
      // a draft challan has not dispatched anything - his rule, 23 Aug 2026:
      // "anything inside dc draft shouldnt be considered yet ... only after submit".
      // So a block on a draft stays selectable; we only say so, quietly.
      var dc = (v && typeof v === 'object') ? v.dc : v;
      var isDraft = (v && typeof v === 'object') ? !!v.draft : false;
      if(dc && !isDraft){
        badge.style.background='#faeeda'; badge.style.color='#8a5a12'; badge.textContent='\u25B2 '+dc;
        r.style.opacity='0.78'; r.style.background='#fbf6ee';
        var cb=r.querySelector('input[type=checkbox]'); if(cb&&cb.checked){ cb.checked=false; cb.dispatchEvent(new Event('change',{bubbles:true})); }
      } else if(dc && isDraft){
        badge.style.background='#eef1f5'; badge.style.color='#5b6672'; badge.textContent='\u25C7 draft '+dc+' \u00b7 not dispatched';
        badge.title='This block is listed on '+dc+', which is still a draft. A draft challan does not count until it is submitted, so the block is still available.';
        r.style.opacity=''; r.style.background='';
      } else {
        badge.style.background='#e1f5ee'; badge.style.color='#0f6e56'; badge.textContent='\u25CF Available';
        r.style.opacity=''; r.style.background='';
      }
      cell.appendChild(badge);
    });
  }});
}
function dolphin_dim_scan(){ document.querySelectorAll('.modal.show, .modal.in, .modal-dialog').forEach(function(m){ try{ dolphin_dim_one(m); }catch(e){} }); }

