  var prevOnload = S.onload;
  S.onload = function(listview){
    if(prevOnload){ try{ prevOnload(listview); }catch(e){} }
    try{
      if(!frappe.route_options && !listview.__dolphin_draft_init){
        listview.__dolphin_draft_init = true;
        listview.__dolphin_dc_tab = 0;
        listview.filter_area.clear().then(function(){
          listview.filter_area.add([['Delivery Challan','docstatus','=',0]]);
        });
      }
    }catch(e){}
  };

  var prevRefresh = S.refresh;
  S.refresh = function(listview){
    if(prevRefresh){ try{ prevRefresh(listview); }catch(e){} }
    try{ renderToggle(listview); }catch(e){}
  };

  function setTab(listview, ds){
    listview.__dolphin_dc_tab = ds;
    Promise.resolve(listview.filter_area.clear()).then(function(){
      listview.filter_area.add([['Delivery Challan','docstatus','=',ds]]);
    });
    highlight(listview, ds);
  }

  function highlight(listview, ds){
    var $t = listview.page.wrapper.find('.dolphin-dc-toggle');
    $t.find('button').removeClass('btn-primary').addClass('btn-default');
    $t.find('button[data-ds="'+ds+'"]').removeClass('btn-default').addClass('btn-primary');
  }

  function renderToggle(listview){
    var $w = listview.page.wrapper;
    if($w.find('.dolphin-dc-toggle').length){ return; }
    var cur = (listview.__dolphin_dc_tab===1)?1:0;
    var html = ''
      + '<div class="dolphin-dc-toggle btn-group btn-group-sm" role="group" style="margin:4px 0 12px 0;">'
      +   '<button type="button" class="btn '+(cur===0?'btn-primary':'btn-default')+'" data-ds="0">Active</button>'
      +   '<button type="button" class="btn '+(cur===1?'btn-primary':'btn-default')+'" data-ds="1">Dispatched / Transported</button>'
      + '</div>';
    var $toggle = $(html);
    var $anchor = $w.find('.layout-main-section .frappe-list').first();
    if(!$anchor.length){ $anchor = $w.find('.layout-main-section').first(); }
    if(!$anchor.length){ $anchor = $w.find('.page-form').first(); }
    $anchor.prepend($toggle);
    $toggle.on('click','button',function(){
      var ds = parseInt($(this).attr('data-ds'),10) || 0;
      setTab(listview, ds);
    });
  }
})();

