async function di_dc_fill_row(frm, cdt, cdn){
  var row = locals[cdt][cdn];
  if(!row || !row.block) return;
  var q = (await frappe.db.get_value('Quarry Block', row.block, ['block_number','export_block_no','buyer_inspection','granite_quality_grade','gross_volume','gross_tonnage','pit'])).message || {};
  if(q.block_number && !row.block_no) frappe.model.set_value(cdt,cdn,'block_no', q.block_number);
  if(q.granite_quality_grade && !row.grade) frappe.model.set_value(cdt,cdn,'grade', q.granite_quality_grade);
  if(!row.export_block_no){ var exp=q.export_block_no||null; if(!exp){ try{ var er=(await frappe.call({method:'frappe.client.get_list',args:{doctype:'Buyer Inspection Block',parent:'Buyer Inspection',filters:[['block','=',row.block]],fields:['export_block_no'],limit_page_length:20}})).message||[]; for(var k=0;k<er.length;k++){ if(er[k].export_block_no){ exp=er[k].export_block_no; break; } } }catch(e){} } if(exp) frappe.model.set_value(cdt,cdn,'export_block_no', exp); }
  var bi = (/^BI-/.test(row.source_inspection||"") ? row.source_inspection : (/^BI-/.test(q.buyer_inspection||"") ? q.buyer_inspection : null));
  if(bi && !row.source_inspection) frappe.model.set_value(cdt,cdn,'source_inspection', bi);
  if(bi){
    try{
      var d = (await frappe.call({method:'frappe.client.get', args:{doctype:'Buyer Inspection', name:bi}})).message;
      var m = (d.block_rows||[]).find(function(x){ return x.block===row.block || x.block_no===row.block_no; });
      if(m && m.export_block_no) frappe.model.set_value(cdt,cdn,'export_block_no', m.export_block_no);
    }catch(e){}
  }
}
frappe.ui.form.on('DC Block Row', {
