function dc_amount(frm){
  var amt=(frm.doc.rate_per_mt||0)*(frm.doc.total_tonnage||0);
  frm.set_value('total_amount', Math.round(amt*100)/100);
}
function dc_override_ui(frm){
  var ov=!!frm.doc.allow_total_override;
  frm.set_df_property('total_volume','read_only', ov?0:1);
  frm.set_df_property('total_tonnage','read_only', ov?0:1);
}
function dc_totals(frm){
  var tv=0,tt=0,n=0;
  (frm.doc.dc_block_rows||[]).forEach(function(r){tv+=r.gross_volume||0; tt+=r.gross_tonnage||0; n++;});
  tv=Math.round(tv*100)/100; tt=Math.round(tt*100)/100;
  frm.set_value('auto_total_volume',tv);
  frm.set_value('auto_total_tonnage',tt);
  frm.set_value('block_count',n);
  if(!frm.doc.allow_total_override){
    frm.set_value('total_volume',tv);
    frm.set_value('total_tonnage',tt);
  }
  dc_amount(frm);
}
function dc_recalc_row(frm,cdt,cdn){
  var r=locals[cdt][cdn]; if(!r) return;
  var L=r.length_gross||0,W=r.width_gross||0,H=r.height_gross||0;
  if(L>0&&W>0&&H>0){
    var vol=Math.round(L*W*H/1000000*10000)/10000;
    frappe.model.set_value(cdt,cdn,'gross_volume',vol);
    var f=r.tonnage_factor||0;
    if(f>0){ frappe.model.set_value(cdt,cdn,'gross_tonnage',Math.round(vol*f*100)/100); }
  }
  setTimeout(function(){dc_totals(frm);},300);
}
frappe.ui.form.on('DC Block Row',{
  block:function(frm,cdt,cdn){
    var row=locals[cdt][cdn];
    if(!row||!row.block){ dc_totals(frm); return; }
    frappe.db.get_value('Quarry Block', row.block, ['length_gross','width_gross','height_gross','gross_volume','gross_tonnage','granite_quality_grade','source_quarry_inspection','tonnage_factor']).then(function(res){
      var b=(res&&res.message)||{};
      frappe.model.set_value(cdt,cdn,'length_gross',b.length_gross||0);
      frappe.model.set_value(cdt,cdn,'width_gross',b.width_gross||0);
      frappe.model.set_value(cdt,cdn,'height_gross',b.height_gross||0);
      frappe.model.set_value(cdt,cdn,'gross_volume',b.gross_volume||0);
      frappe.model.set_value(cdt,cdn,'gross_tonnage',b.gross_tonnage||0);
      frappe.model.set_value(cdt,cdn,'grade',b.granite_quality_grade||'');
      frappe.model.set_value(cdt,cdn,'source_inspection',b.source_quarry_inspection||'');
      frappe.model.set_value(cdt,cdn,'tonnage_factor',b.tonnage_factor||0);
      dc_totals(frm);
    });
  },
  dc_block_rows_remove:function(frm){ dc_totals(frm); },
  length_gross:function(frm,cdt,cdn){ dc_recalc_row(frm,cdt,cdn); },
  width_gross:function(frm,cdt,cdn){ dc_recalc_row(frm,cdt,cdn); },
  height_gross:function(frm,cdt,cdn){ dc_recalc_row(frm,cdt,cdn); }
});
frappe.ui.form.on('Delivery Challan',{
  refresh:function(frm){ dc_override_ui(frm); },
  allow_total_override:function(frm){ dc_override_ui(frm); if(!frm.doc.allow_total_override){ dc_totals(frm); } },
  rate_per_mt:function(frm){ dc_amount(frm); },
  total_tonnage:function(frm){ dc_amount(frm); },
  validate:function(frm){
    dc_totals(frm);
    var n=(frm.doc.dc_block_rows||[]).length;
    if(n<1||n>12){ frappe.throw(__('A Delivery Challan must have between 1 and 12 blocks (currently '+n+').')); }
  },
  on_submit:function(frm){
    var chain=Promise.resolve();
    (frm.doc.dc_block_rows||[]).forEach(function(r){
      if(!r.block) return;
      chain=chain.then(function(){return frappe.call({method:'frappe.client.set_value',args:{doctype:'Quarry Block',name:r.block,fieldname:{status:'Dispatched/Transported',delivery_challan:frm.doc.name}}});});
    });
    chain.then(function(){frappe.show_alert({message:frm.doc.block_count+' block(s) marked Dispatched/Transported',indicator:'green'});});
  },
  on_cancel:function(frm){
    var chain=Promise.resolve();
    (frm.doc.dc_block_rows||[]).forEach(function(r){
      if(!r.block) return;
      chain=chain.then(function(){return frappe.call({method:'frappe.client.set_value',args:{doctype:'Quarry Block',name:r.block,fieldname:{status:'In Stock',delivery_challan:''}}});});
    });
    chain.then(function(){frappe.show_alert({message:'Blocks returned to In Stock',indicator:'orange'});});
  }
});

