frappe.ui.form.on('Delivery Challan', {
  refresh(frm){
    if(frm.is_new()) return;
    var w=frm.fields_dict.report_activity_panel; if(!w) return;
    var canVer = frappe.model.can_read('Version');
    var canHist = frappe.model.can_read('Block Measurement History');
    if(!canVer && !canHist){ w.$wrapper.html('<div style="padding:8px;color:#999;font-size:12px">Activity history is available to admins.</div>'); return; }
    w.$wrapper.html('<div style="padding:8px;color:#888">Loading activity...</div>');
    var ids=(frm.doc.dc_block_rows||[]).map(function(r){return r.block;}).filter(Boolean);
    var qbP = ids.length? frappe.db.get_list('Quarry Block',{filters:[['name','in',ids]],fields:['name','block_number'],limit:0}).catch(function(){return [];}) : Promise.resolve([]);
    qbP.then(function(qbs){
      var names=(qbs||[]).map(function(x){return x.name;});
      var num={}; (qbs||[]).forEach(function(x){num[String(x.name)]=x.block_number;});
      var histP = (canHist && names.length)? frappe.db.get_list('Block Measurement History',{filters:[['parenttype','=','Quarry Block'],['parent','in',names]],fields:['parent','measured_on','event_type','length_gross','width_gross','height_gross','gross_volume'],order_by:'measured_on desc',limit:40}).catch(function(){return [];}) : Promise.resolve([]);
      var verP = canVer? frappe.db.get_list('Version',{filters:[['ref_doctype','=',frm.doctype],['docname','=',frm.doc.name]],fields:['owner','creation','data'],order_by:'creation desc',limit:20}).catch(function(){return [];}) : Promise.resolve([]);
      Promise.all([verP,histP]).then(function(res){
        var vers=res[0]||[], hist=res[1]||[];
        function isInit(v){ return v===null||v===undefined||v===''||v===0||v==='0'; }
        function fmt(v){ return (v===null||v===undefined||v==='')?'(blank)':v; }
        function vsum(s){ try{var d=JSON.parse(s||'{}');var p=[];
          (d.changed||[]).forEach(function(c){ if(isInit(c[1])) return; p.push(c[0]+': '+fmt(c[1])+' to '+fmt(c[2])); });
          (d.row_changed||[]).forEach(function(rc){ (rc[3]||[]).forEach(function(c){ if(isInit(c[1])) return; p.push(c[0]+': '+fmt(c[1])+' to '+fmt(c[2])); }); });
          (d.added||[]).forEach(function(a){ p.push('row added'); });
          (d.removed||[]).forEach(function(a){ p.push('row removed'); });
          return p.slice(0,6).join('; ');
        }catch(e){ return ''; } }
        var h='<div style="border:1px solid #e2e2e2;border-radius:8px;overflow:hidden"><div style="background:#0F2540;color:#fff;padding:6px 10px;font-weight:600">Report Activity</div><div style="padding:8px 10px">';
        if(canVer){
          h+='<div style="font-weight:600;margin-bottom:4px">This report</div>';
          var shown=0;
          vers.forEach(function(v){ var sm=vsum(v.data); if(!sm) return; shown++; h+='<div style="border-left:3px solid #b8860b;background:#fff7e0;padding:4px 8px;margin:3px 0;font-size:12px"><b>'+frappe.datetime.str_to_user(v.creation)+'</b> &middot; '+(v.owner||'')+' &mdash; '+sm+'</div>'; });
          if(!shown) h+='<div style="color:#888;font-size:12px">No edits since creation.</div>';
        }
        if(canHist){
          h+='<div style="font-weight:600;margin:10px 0 4px">Blocks</div>';
          if(!hist.length) h+='<div style="color:#888;font-size:12px">No block measurement changes.</div>';
          hist.forEach(function(r){ var ev=String(r.event_type||'').toLowerCase(); var green=(ev.indexOf('creat')>-1||ev.indexOf('initial')>-1); var col=green?'#1f7a1f':'#b8860b'; var bg=green?'#eafaea':'#fff7e0'; h+='<div style="border-left:3px solid '+col+';background:'+bg+';padding:4px 8px;margin:3px 0;font-size:12px">Block <b>'+(num[String(r.parent)]||r.parent)+'</b> &middot; <span style="color:'+col+';font-weight:600">'+(r.event_type||'')+'</span> &middot; '+(r.measured_on?frappe.datetime.str_to_user(r.measured_on):'')+' &middot; L'+(r.length_gross||'')+' W'+(r.width_gross||'')+' H'+(r.height_gross||'')+'</div>'; });
        }
        h+='</div></div>';
        w.$wrapper.html(h);
      });
    });
  }
});

