(function(){
  var CCACHE=null, CLOADING=false;
  function ensureCache(){
    if(CCACHE||CLOADING) return; CLOADING=true;
    var dcP=fetch('/api/method/frappe.client.get_list?doctype=Delivery%20Challan&fields='+encodeURIComponent('["name","export_consignee","buyer"]')+'&limit_page_length=0',{credentials:'same-origin'}).then(function(r){return r.json();}).then(function(j){return j.message||[];});
    var ecP=fetch('/api/method/frappe.client.get_list?doctype=Export%20Consignee&fields='+encodeURIComponent('["name","company_name"]')+'&limit_page_length=0',{credentials:'same-origin'}).then(function(r){return r.json();}).then(function(j){return j.message||[];});
    Promise.all([dcP,ecP]).then(function(res){ var ecMap={}; res[1].forEach(function(e){ecMap[e.name]=e.company_name||e.name;}); var m={}; res[0].forEach(function(d){ m[d.name]= d.buyer || (d.export_consignee?(ecMap[d.export_consignee]||d.export_consignee):'') || ''; }); CCACHE=m; }).catch(function(){CLOADING=false;});
  }
  function openPreview(name){
    var fmt='Dolphin Delivery Challan';
    var viewUrl='/printview?doctype=Delivery%20Challan&name='+encodeURIComponent(name)+'&trigger_print=0&format='+encodeURIComponent(fmt)+'&no_letterhead=0';
    var pdfUrl='/api/method/frappe.utils.print_format.download_pdf?doctype=Delivery%20Challan&name='+encodeURIComponent(name)+'&format='+encodeURIComponent(fmt)+'&no_letterhead=0';
    var d=new frappe.ui.Dialog({title:name+' — preview', size:'extra-large', fields:[{fieldtype:'HTML',fieldname:'p'}]});
    d.fields_dict.p.$wrapper.html('<div style="display:flex;justify-content:flex-end;gap:8px;margin-bottom:8px"><a href="'+viewUrl+'" target="_blank" class="btn btn-sm btn-primary">Open full page &#8599;</a><a href="'+pdfUrl+'" target="_blank" class="btn btn-sm btn-default">Download PDF</a></div><iframe src="'+viewUrl+'" style="width:100%;height:72vh;border:1px solid #e5e7eb;border-radius:6px;background:#fff"></iframe>');
    d.show();
  }
  function doPrint(name){ window.open('/printview?doctype=Delivery%20Challan&name='+encodeURIComponent(name)+'&trigger_print=1&format='+encodeURIComponent('Dolphin Delivery Challan')+'&no_letterhead=0','_blank'); }
  function mkIcon(cls,iconName,title,handler){ var e=document.createElement('span'); e.className=cls; e.style.cssText='cursor:pointer;margin-left:8px;color:#185fa5;vertical-align:middle;display:inline-flex'; try{e.innerHTML=frappe.utils.icon(iconName,'sm');}catch(err){e.innerHTML=title;} e.title=title; e.addEventListener('click',function(ev){ev.preventDefault();ev.stopPropagation();handler();}); return e; }
  function inject(){
    if((location.pathname||'').indexOf('delivery-challan')<0) return;
    ensureCache();
    document.querySelectorAll('.list-row').forEach(function(row){
      var cols=row.querySelectorAll('.list-row-col'); if(!cols.length) return;
      var name=(cols[0].innerText||'').trim();
      // icons in status column
      if(!row.querySelector('.dc-preview-eye')){
        var stat=null; cols.forEach(function(c){var f=c.querySelector('[data-filter]'); if(f&&/^docstatus,/.test(f.getAttribute('data-filter')||'')) stat=c;});
        if(stat&&name){ stat.appendChild(mkIcon('dc-preview-eye','view','Preview',function(){openPreview(name);})); stat.appendChild(mkIcon('dc-print-icon','printer','Print',function(){doPrint(name);})); }
      }
      // fill buyer/consignee column if empty
      if(CCACHE&&name&&!row.querySelector('.dc-consignee-fill')){
        var bcol=null; cols.forEach(function(c){var f=c.querySelector('[data-filter]'); if(f&&/^buyer,/.test(f.getAttribute('data-filter')||'')) bcol=c;});
        if(bcol && !(bcol.innerText||'').trim() && CCACHE[name]){ var s=document.createElement('span'); s.className='dc-consignee-fill'; s.style.cssText='color:#33445c'; s.textContent=CCACHE[name]; bcol.appendChild(s); }
      }
    });
  }
  setInterval(inject,1000);
})();

