frappe.ui.form.on('Delivery Challan', {
  validate: function(frm){
    var rows = (frm.doc.dc_block_rows || []);
    // drop completely-empty placeholder rows
    var kept = rows.filter(function(r){ return r.block || r.block_number_input || r.length_gross || r.export_block_no; });
    if(kept.length !== rows.length){ frm.doc.dc_block_rows = kept; frm.refresh_field('dc_block_rows'); }
    // flag rows with input/data but no resolved block
    var bad=[], seen={}, dup=[];
    kept.forEach(function(r, i){
      if(!r.block){ bad.push('Row '+(i+1)+(r.block_number_input ? (' \u2014 "'+r.block_number_input+'"') : '')); return; }
      if(seen[r.block]){ dup.push(r.block_no || r.block); } seen[r.block]=1;
    });
    if(bad.length){ frappe.throw({title:'Unresolved block rows', message:'These rows have no valid block. Enter a Quarry/Export number that resolves, or remove the row:<br><b>'+bad.join('<br>')+'</b>'}); }
    if(dup.length){ frappe.throw({title:'Duplicate blocks', message:'The same block is added more than once: <b>'+[...new Set(dup)].join(', ')+'</b>. Remove the duplicates.'}); }
  }
});

