  after_save: function(frm){ buildFullLot(frm).then(function(t){ if(t && (!frm.doc.lot_title || frm.doc.lot_title===frm.__auto)){ frm.__auto=t; frappe.db.set_value('Export Shipment Lot', frm.doc.name, 'lot_title', t).then(function(){ frm.reload_doc(); }); } }); }
});
function _cl(s){return (''+(s||'')).replace(/\s+/g,' ').trim();}
function _tc(s){return _cl(s).replace(/\w\S*/g,function(t){return t.charAt(0).toUpperCase()+t.slice(1).toLowerCase();});}
function _sh(c){var w=_cl(c).replace(/[.,&\/]/g,' ').replace(/\s+/g,' ').trim().split(/\s+/);var o=[];for(var i=0;i<w.length;i++){if(/^(import|export|exports|imports|co|ltd|pvt|private|limited|company|inc|and|trading|international)$/i.test(w[i]))break;o.push(w[i]);if(o.length>=2)break;}return _tc(o.join(' '));}
function _dt(d){var M=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];if(!d)return '';var p=(''+d).slice(0,10).split('-');return p[2]+'-'+M[(+p[1]||1)-1]+'-'+p[0].slice(2);}
function _nm(nm){var m=(''+nm).match(/(\d+)\s*$/);return m?String(+m[1]):'';}
function _ownNick(frm){var fn=_cl((frappe.user_info(frm.doc.owner)||{}).fullname||''); return /^administrator$/i.test(fn)?'':fn;}
function _join(a){return a.filter(function(x){return x && x!=='#';}).join(' \u00b7 ');}
function _buyer(frm){ if(!frm.doc.export_consignee) return Promise.resolve(''); return frappe.db.get_value('Export Consignee', frm.doc.export_consignee, 'company_name').then(function(r){ return _sh((r&&r.message&&r.message.company_name)||frm.doc.export_consignee); }); }
function _insp(blocks){ var chain=Promise.resolve(''); (blocks||[]).forEach(function(b){ chain=chain.then(function(f){ if(f||!b.block)return f; return frappe.db.get_value('Quarry Block', b.block, 'buyer_inspection').then(function(r){ var bin=r&&r.message&&r.message.buyer_inspection; if(!bin)return ''; return frappe.call({method:'frappe.client.get',args:{doctype:'Buyer Inspection',name:bin}}).then(function(d){ var rows=(d.message&&d.message.buyer_inspector_name)||[]; return rows.map(function(x){return x.buyer_inspector;}).filter(Boolean)[0]||''; }); }); }); }); return chain; }
function buildFullLot(frm){ return Promise.all([_buyer(frm), _insp(frm.doc.blocks)]).then(function(a){ return _join([a[0], _tc(a[1]), _cl(frm.doc.shipping_mark), _ownNick(frm), _dt(frm.doc.shipment_date), '#'+_nm(frm.doc.name)]); }); }
function regenLot(frm){ buildFullLot(frm).then(function(t){ if(t && (!frm.doc.lot_title || frm.doc.lot_title===frm.__auto)){ frm.__auto=t; frm.set_value('lot_title', t); } }); }

