function dolphin_paste_blocks(frm){
  var rows=[];
  var d=new frappe.ui.Dialog({title:'Emergency paste \u2014 '+frm.doc.name, size:'extra-large',
    fields:[
      {fieldtype:'HTML', fieldname:'help', options:'<div style="font-size:12px;color:#5f6b7a;margin-bottom:6px">Paste one block per line: <b>Export No</b> then optional <b>L W H CBM</b> (tab/space separated). Emergency use: At-Port / BI / lot checks are shown as warnings but never block \u2014 override to print export docs now, reconcile to stock later.</div>'},
      {fieldtype:'Small Text', fieldname:'raw', label:'Paste rows', reqd:1},
      {fieldtype:'Button', fieldname:'verify', label:'Verify'},
      {fieldtype:'HTML', fieldname:'preview'}
    ],
    primary_action_label:'Add (override)',
    primary_action:function(){ doAdd(); }
  });
  function parse(){return (d.get_value('raw')||'').split(/\r?\n/).map(function(l){return l.trim();}).filter(Boolean).map(function(l){var p=l.split(/[\t ,]+/);return {no:p[0],L:+p[1]||0,W:+p[2]||0,H:+p[3]||0,cbm:+p[4]||0};});}
  function verify(){var items=parse(); if(!items.length){frappe.msgprint('Paste some rows first.');return;}
    var byNo={}; items.forEach(function(x){byNo[x.no]=x;});
    frappe.call({method:'dolphin_theme.api_arrivals.paste_verify', args:{lot:frm.doc.name, numbers:items.map(function(x){return x.no;})}, freeze:true, callback:function(r){
      var res=r.message||[];
      rows=res.map(function(v){var p=byNo[v.input]||{};
        var L=v.found?v.L:(p.L||0),W=v.found?v.W:(p.W||0),H=v.found?v.H:(p.H||0);
        var cbm=v.found?v.cbm:(p.cbm||(L*W*H/1e6));
        var w=(v.warnings||[]).slice();
        if(v.found&&p.L&&(p.L!=v.L||p.W!=v.W||p.H!=v.H))w.push('msmt differs from system');
        if(!v.found)w.push('Not in system \u2014 using pasted msmt');
        return {no:v.input,found:v.found,block:v.block||null,block_no:v.block_no||v.input,export_no:v.export_no||v.input,grade:v.grade||'',L:L,W:W,H:H,cbm:cbm,status:v.status||'',warnings:w,include:1};
      });
      render();
    }});
  }
  function render(){var esc=frappe.utils.escape_html;
    var h='<table class="table table-bordered" style="font-size:12px;margin-top:8px"><thead><tr><th>+</th><th>Export No</th><th>Match</th><th>Grade</th><th>L\u00d7W\u00d7H</th><th>CBM</th><th>Status</th><th>Warnings</th></tr></thead><tbody>';
    rows.forEach(function(r,i){h+='<tr><td><input type="checkbox" class="pchk" data-i="'+i+'" '+(r.include?'checked':'')+'></td><td><b>'+esc(r.export_no)+'</b></td><td>'+(r.found?esc(r.block_no):'<span style="color:#c0392b">new</span>')+'</td><td>'+esc(r.grade)+'</td><td>'+r.L+'\u00d7'+r.W+'\u00d7'+r.H+'</td><td>'+(r.cbm||0).toFixed(3)+'</td><td>'+esc(r.status)+'</td><td style="color:#b06a1a">'+(r.warnings.length?r.warnings.map(esc).join('; '):'<span style="color:#178a3a">ok</span>')+'</td></tr>';});
    h+='</tbody></table><div style="font-size:12px;color:#5f6b7a">'+rows.length+' row(s). Untick to exclude. Ticked rows add even with warnings (override).</div>';
    d.fields_dict.preview.$wrapper.html(h);
    d.fields_dict.preview.$wrapper.find('.pchk').on('change',function(){rows[+this.dataset.i].include=this.checked;});
  }
  function doAdd(){
 var chosen=rows.filter(function(r){return r.include;});
 if(!chosen.length){frappe.msgprint('Nothing ticked.');return;}
 var offport=chosen.filter(function(r){return (r.status||'')!=='At Port';});
 if(offport.length){
  var lines=offport.map(function(r){return '- '+frappe.utils.escape_html(r.export_no)+' ('+frappe.utils.escape_html(r.status||'not in system')+')';}).join('<br>');
  frappe.confirm('<b>'+offport.length+' block(s) are NOT At Port:</b><br>'+lines+'<br><br>Add them to this lot anyway?', function(){ dolphin_commit_paste(chosen, offport); });
 } else { dolphin_commit_paste(chosen, []); }
}
function dolphin_commit_paste(chosen, offport){
 var payload=chosen.map(function(r){return {block_no:r.block_no,quarry_block:r.block,export_block_no:r.export_no,length:r.L,width:r.W,height:r.H,cbm:r.cbm,mt:(r.cbm*2.6)};});
 frappe.call({method:'dolphin_theme.api_arrivals.add_blocks_to_lot', args:{lot:frm.doc.name, rows:payload}, freeze:true, freeze_message:'Adding...', callback:function(rr){
  var addedN=((rr.message&&rr.message.added)||chosen.length);
  var notes=offport.filter(function(r){return r.block;});
  if(!notes.length){ frappe.show_alert({message:addedN+' block(s) added', indicator:'green'}); d.hide(); frm.reload_doc(); return; }
  var done=0, who=(frappe.session.user_fullname||frappe.session.user);
  function fin(){ if(done===notes.length){ frappe.show_alert({message:addedN+' block(s) added; '+notes.length+' history note(s) written', indicator:'green'}); d.hide(); frm.reload_doc(); } }
  notes.forEach(function(r){
   var src=r.status||'not in system';
   var content='Added to Export Shipment Lot '+frm.doc.name+' from '+src+' (manual override) by '+who;
   frappe.call({method:'frappe.desk.form.utils.add_comment', args:{reference_doctype:'Quarry Block', reference_name:r.block, content:content, comment_email:frappe.session.user, comment_by:who}, callback:function(){ done++; fin(); }, error:function(){ done++; fin(); }});
  });
 }});
}
 d.fields_dict.verify.$input.on('click', verify);
  d.show();
}

