  block: function(frm, cdt, cdn){
    var row = locals[cdt][cdn]; if(!row.block) return;
    frappe.db.get_value('Quarry Block', row.block, ['block_number','gross_volume','gross_tonnage','granite_quality_grade']).then(function(r){
      var m = r && r.message; if(!m) return;
      if(m.gross_volume && !row.gross_volume) frappe.model.set_value(cdt,cdn,'gross_volume', m.gross_volume);
      if(m.gross_tonnage && !row.quantity_mt) frappe.model.set_value(cdt,cdn,'quantity_mt', m.gross_tonnage);
