      setTimeout(function(){ recalc(frm); }, 300);
    });
  },
  quantity_mt: function(frm){ recalc(frm); },
  blocks_remove: function(frm){ recalc(frm); }
});
function recalc(frm){
  var rows = frm.doc.blocks || [];
  var qty = 0; rows.forEach(function(r){ qty += (r.quantity_mt||0); });
  var taxable = qty * (frm.doc.rate_per_mt||0);
  var inter = !(/karnat/i.test(frm.doc.buyer_state||'Karnataka'));
  var cgst=0,sgst=0,igst=0;
  if(inter){ igst = taxable*0.05; } else { cgst = taxable*0.025; sgst = taxable*0.025; }
  var raw = taxable + cgst + sgst + igst;
  var grand = Math.round(raw);
  function R2(x){ return Math.round(x*100)/100; }
  frm.set_value('block_count', rows.length);
  frm.set_value('total_quantity_mt', Math.round(qty*1000)/1000);
  frm.set_value('taxable_value', R2(taxable));
  frm.set_value('is_interstate', inter?1:0);
  frm.set_value('cgst_amount', R2(cgst));
  frm.set_value('sgst_amount', R2(sgst));
  frm.set_value('igst_amount', R2(igst));
  frm.set_value('rounded_off', R2(grand - raw));
  frm.set_value('grand_total', grand);
}

// Dolphin Day31: Local Tax Invoice - owns calc for BOTH crude (rate x crude qty) and block (rate x sum block qty).
frappe.ui.form.on('Local Tax Invoice', {
  refresh: function(frm){ di_lti_invno(frm); di_lti_desc(frm); di_lti_pos(frm); },
  validate: function(frm){ di_lti_calc(frm); di_lti_invno(frm); },
  buyer_state: function(frm){ di_lti_pos(frm); di_lti_calc(frm); },
  place_of_supply: function(frm){ di_lti_pos(frm); },
  is_interstate: function(frm){ di_lti_calc(frm); },
  description: function(frm){ di_lti_desc(frm); },
  rate_per_mt: function(frm){ di_lti_calc(frm); },
  crude_qty_mt: function(frm){ di_lti_calc(frm); },
  dmg_charges_per_ton: function(frm){ di_lti_calc(frm); },
