function di_lti_invno(frm){ if(!frm.is_new() && frm.doc.name && frm.doc.invoice_no!==frm.doc.name){ frm.set_value('invoice_no', frm.doc.name); } }
function di_lti_pos(frm){ var st=(frm.doc.buyer_state||'').trim(); if(!st) return; if((frm.doc.place_of_supply||'')!==st) frm.set_value('place_of_supply', st); var inter = st.toLowerCase().indexOf('karnataka')===-1; if(!!frm.doc.is_interstate!==inter) frm.set_value('is_interstate', inter?1:0); }
function di_lti_desc(frm){ var d=frm.doc.description; var crude=false; function paint(){ frm.toggle_display('blocks', !crude); frm.toggle_display('block_count', !crude); frm.toggle_display('total_quantity_mt', !crude); frm.toggle_display('crude_pieces', crude); frm.toggle_display('crude_qty_mt', crude); di_lti_calc(frm); } if(!d){ frm.__di_crude=false; paint(); return; } frappe.db.get_value('Goods Description', d, ['is_crude','default_hsn']).then(function(r){ var v=(r&&r.message)||{}; crude=!!v.is_crude; frm.__di_crude=crude; if(v.default_hsn && !frm.doc.hsn){ frm.set_value('hsn', v.default_hsn); } paint(); }); }
function di_lti_qty(frm){ if(frm && frm.doc && frm.doc.allow_override){return;}  if(frm.__di_crude) return flt(frm.doc.crude_qty_mt); var s=0; (frm.doc.blocks||[]).forEach(function(b){ s+=flt(b.quantity_mt); }); return s; }
function di_lti_calc(frm){ if(frm && frm.doc && frm.doc.allow_override){return;}  var qty=di_lti_qty(frm); var rate=flt(frm.doc.rate_per_mt); var taxable=qty*rate; var inter=frm.doc.is_interstate?1:0; var cgst=0,sgst=0,igst=0; if(inter){igst=taxable*0.05;}else{cgst=taxable*0.025;sgst=taxable*0.025;} var raw=taxable+cgst+sgst+igst+(flt(frm.doc.dmg_charges_per_ton)*qty); var grand=Math.round(raw); var dmg=flt(frm.doc.dmg_charges_per_ton)*qty; var bc=frm.__di_crude?0:(frm.doc.blocks||[]).length; var set={total_quantity_mt:qty,block_count:bc,taxable_value:taxable,cgst_amount:cgst,sgst_amount:sgst,igst_amount:igst,rounded_off:(grand-raw),grand_total:grand,dmg_charges:dmg}; Object.keys(set).forEach(function(k){ if(flt(frm.doc[k])!==flt(set[k])){ frm.doc[k]=set[k]; frm.refresh_field(k); } }); }

