    if(!f || !f.$input || f.$input.data('di-dd')) return;
    f.$input.data('di-dd', 1);
    f.$input.on('focus', function(){
      if(f.awesomplete){ f.awesomplete.minChars = 0; f.awesomplete.filter = function(){ return true; }; }
      var inp = this, $i = $(inp);
      $i.data('di-val', $i.val() || '');
      if($i.val()){ $i.val(''); }
      setTimeout(function(){ $i.trigger('input'); }, 60);
    });
    f.$input.on('blur', function(){
      var inp = this, $i = $(inp);
      setTimeout(function(){
