frappe.ui.form.on('Tax Invoice Block', {
  block_number_input: function(frm, cdt, cdn){
    var row = locals[cdt][cdn];
    var inp = (row.block_number_input || '').toString().trim();
    if(!inp) return;
    var FL=['block','block_no','length_gross','width_gross','height_gross','gross_volume','quantity_mt'];
    function doClear(){ FL.forEach(function(f){ frappe.model.set_value(cdt,cdn,f,''); }); frappe.model.set_value(cdt,cdn,'block_number_input',''); frm.refresh_field('blocks'); }
    function reject(msg){ doClear(); setTimeout(doClear,350); frappe.show_alert({message:msg+' Field cleared — enter another.', indicator:'orange'},6); }
    function recalc(){ var t=0;(frm.doc.blocks||[]).forEach(function(x){t+=(x.quantity_mt||0);}); frm.set_value('total_quantity_mt', Math.round(t*1000)/1000); try{frm.script_manager.trigger('total_quantity_mt');}catch(e){} }
    frappe.call({method:'frappe.client.get_list',args:{doctype:'Quarry Block',or_filters:[['block_number','=',inp],['export_block_no','=',inp]],fields:['name','block_number','export_block_no','status','length_gross','width_gross','height_gross','gross_volume','gross_tonnage'],limit_page_length:5},callback:function(r){
      var rows=r.message||[];
      if(!rows.length){ reject('No block found for "'+inp+'".'); return; }
      var a=rows.filter(function(x){return String(x.block_number)===inp;})[0];
      var e=rows.filter(function(x){return String(x.export_block_no)===inp;})[0];
      var b=a||e; var matchedBy=a?'Quarry No':'Export No';
      var dup=(frm.doc.blocks||[]).some(function(x){return x.name!==cdn && String(x.block)===String(b.name);});
      if(dup){ reject('Block '+b.block_number+' already added.'); return; }
      if(b.status!=='In Stock'){ reject(b.block_number+' is '+b.status+', not free stock.'); return; }
      frappe.model.set_value(cdt,cdn,'block',b.name);
      frappe.model.set_value(cdt,cdn,'block_no',b.block_number);
      frappe.model.set_value(cdt,cdn,'length_gross',b.length_gross);
      frappe.model.set_value(cdt,cdn,'width_gross',b.width_gross);
      frappe.model.set_value(cdt,cdn,'height_gross',b.height_gross);
      frappe.model.set_value(cdt,cdn,'gross_volume',b.gross_volume);
      frappe.model.set_value(cdt,cdn,'quantity_mt',b.gross_tonnage);
      frm.refresh_field('blocks'); recalc();
      frappe.show_alert({message:'Matched '+inp+' ('+matchedBy+') → Quarry '+b.block_number+', In Stock.', indicator:'green'},5);
    }});
  }
});

frappe.ui.form.on('Local Tax Invoice', {
  validate: function(frm){
    var rows=(frm.doc.blocks||[]);
    var kept=rows.filter(function(r){ return r.block || r.block_number_input || r.quantity_mt; });
    if(kept.length!==rows.length){ frm.doc.blocks=kept; frm.refresh_field('blocks'); }
    var bad=[],seen={},dup=[];
    kept.forEach(function(r,i){ if(!r.block){ bad.push('Row '+(i+1)+(r.block_number_input?(' \u2014 "'+r.block_number_input+'"'):'')); return;} if(seen[r.block]){dup.push(r.block_no||r.block);} seen[r.block]=1; });
    if(bad.length){ frappe.throw({title:'Unresolved block rows', message:'Fix or remove:<br><b>'+bad.join('<br>')+'</b>'}); }
    if(dup.length){ frappe.throw({title:'Duplicate blocks', message:'<b>'+[...new Set(dup)].join(', ')+'</b>'}); }
  }
});

