async function parse_attachment(frm){
  const url = await find_attachment(frm);
  if(!url){ frappe.msgprint('No .xls attachment found on this record or its email. Upload one in "Email Attachment".'); return; }
  try{
    await load_sheetjs();
    const resp=await fetch(url,{credentials:'include'});
    const buf=await resp.arrayBuffer();
    const wb=XLSX.read(new Uint8Array(buf),{type:'array'});
    let sheetName=frm.doc.source_sheet&&wb.SheetNames.includes(frm.doc.source_sheet)?frm.doc.source_sheet:null;
    let parsedRows=[];
    const names=sheetName?[sheetName]:wb.SheetNames;
    for(const sn of names){const aoa=XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,raw:true,defval:''});parsedRows=parsedRows.concat(parse_sheet(aoa,sn));if(sheetName)break;}
    if(!parsedRows.length){frappe.msgprint('No block rows detected. Check the file / sheet name.');return;}
    const _dedup = await frappe.call({method:'dolphin_theme.api_arrivals.upsert_arrival',args:{rows:JSON.stringify(parsedRows),source_file:frm.doc.source_file||null,current:frm.doc.name||null,meta:JSON.stringify({shipper:frm.doc.shipper,mark:frm.doc.mark,arrival_date:frm.doc.arrival_date,port:frm.doc.port,vessel:frm.doc.vessel,booking_no:frm.doc.booking_no,email_subject:frm.doc.email_subject})}}).then(r=>r.message).catch(()=>({action:'none'}));
    if(_dedup&&_dedup.action==='updated'){frappe.show_alert({message:'These blocks already arrived \u2014 updated '+_dedup.name+' instead of creating a duplicate.',indicator:'orange'},9);frappe.set_route('Form','Port Arrival',_dedup.name);return;}
    if(_dedup&&_dedup.action==='partial'){frappe.msgprint({title:'Possible duplicate arrival',message:'These blocks overlap '+_dedup.name+', which has other blocks not in this file. Review before saving so you do not create a duplicate of '+_dedup.name+'.',indicator:'orange'});}
    if(_dedup&&_dedup.action==='ambiguous'){frappe.msgprint({title:'Duplicate blocks across multiple arrivals',message:'These blocks already exist on: '+(_dedup.parents||[]).join(', ')+'. Please resolve those arrivals before parsing here.',indicator:'red'});return;}
    frm.clear_table('blocks');
    parsedRows.forEach(r=>{const row=frm.add_child('blocks');Object.assign(row,r);});
    frm.refresh_field('blocks'); compute_totals(frm);
    frappe.show_alert({message:parsedRows.length+' rows parsed. Now click "Match Blocks".',indicator:'green'});
    await match_blocks(frm,false);
  }catch(e){frappe.msgprint('Parse error: '+e.message);}
}

function find_header(aoa){for(let i=0;i<Math.min(aoa.length,12);i++){const cells=(aoa[i]||[]).map(c=>norm(c).toUpperCase());if(cells.some(c=>/^BLOCK ?NO/.test(c)))return i;}return -1;}
