      rec={block_no:blk,cbm:f2(get(/^CBM/)),ado_no:norm(get(/^AD ?NO/)),calculated_wt:f2(get(/CAL.?CUL?ATED WEIGHT|CALC/)),line_no:norm(get(/LINE ?NO/)),vehicle_no:norm(get(/WAY .?O.? TRANSPORT|VEHICLE/)),row_date:parse_date(get(/^DATE/)),shipper:norm(get(/^SHIPPER/)),mark:norm(get(/^MARKING|^MARK/))};
