window.dolphin_qb_dupcheck = function(lv){
  frappe.db.get_list('Quarry Block',{fields:['block_number','date_produced'],limit:0}).then(function(rows){
    var by={};
    rows.forEach(function(r){ var k=String(r.block_number==null?'':r.block_number).trim(); if(!k) return; (by[k]=by[k]||[]).push(r.date_produced||''); });
    var dups=Object.keys(by).filter(function(k){ return by[k].length>1; });
    if(!dups.length) return;
    var sameDate=dups.filter(function(k){ var seen={},bad=false; by[k].forEach(function(d){ if(seen[d]) bad=true; seen[d]=1; }); return bad; });
    var msg='⚠ '+dups.length+' block number(s) appear more than once'+(sameDate.length?(' — '+sameDate.length+' on the SAME date (likely errors)'):' (on different dates)')+'. Click "Show Duplicates".';
    try{
      var last=parseInt(localStorage.getItem('dolphin_dupalert_ts')||'0',10);
      if(Date.now()-last > 12*3600*1000){
        frappe.show_alert({message:msg, indicator:'red'}, 12);
        localStorage.setItem('dolphin_dupalert_ts', String(Date.now()));
      }
    }catch(e){ frappe.show_alert({message:msg, indicator:'red'}, 12); }
    lv.page.add_inner_button('⚠ Show Duplicates', function(){
      Promise.resolve(lv.filter_area.clear()).then(function(){
        lv.filter_area.add([['Quarry Block','block_number','in',dups]]);
      });
    });
  });
};

// Dolphin: duplicate block number guard
// Same date_produced + same block_number => blocked. Other dates => warn & allow (new UID).
frappe.ui.form.on('Quarry Block', {
  validate(frm){
    if(!frm.doc.block_number) return;
    return new Promise(function(resolve, reject){
      frappe.db.get_list('Quarry Block', {
        filters: [['block_number','=', frm.doc.block_number], ['name','!=', frm.doc.name || '__new__']],
        fields: ['name','date_produced'], limit: 0
      }).then(function(dups){
        if(!dups || !dups.length){ resolve(); return; }
        var d = frm.doc.date_produced || null;
        var sameDate = dups.filter(function(x){ return (x.date_produced||null) === d; });
        if(sameDate.length){
          frappe.msgprint({title:'Duplicate blocked', indicator:'red',
            message:'Block <b>'+frm.doc.block_number+'</b> already exists on the same date ('+(d||'no date')+'). A block number cannot be repeated on the same date.'});
          reject();
          return;
        }
        if(frm.__dup_ok){ resolve(); return; }
        frappe.confirm(
          'Block <b>'+frm.doc.block_number+'</b> already exists on '+dups.length+' other date(s): '+dups.map(function(x){return x.date_produced;}).join(', ')+'.<br><br>Save anyway as a separate block (it gets a new UID)?',
          function(){ frm.__dup_ok = true; frm.save(); },
          function(){ /* cancelled */ }
        );
        reject(); // stop this save; if confirmed, frm.save() re-runs with __dup_ok set
      }).catch(function(){ resolve(); });
    });
  },
  after_save(frm){ frm.__dup_ok = false; }
});

