function dolphin_qb_refs(frm, extra){
  var d = frm.doc;
  return {
    qi: d.source_quarry_inspection || '',
    bi: d.source_buyer_inspection || d.buyer_inspection || '',
    dc: d.delivery_challan || '',
    pa: (extra && extra.pa) || '',
