function dolphin_qb_eye(dt, nm){
  if(!nm) return '';
  return ' <a href="#" class="dj-eye" data-dt="'+dt+'" data-nm="'+frappe.utils.escape_html(nm)+'" title="Open '+dt+'" style="margin-left:5px;text-decoration:none;font-size:13px">&#128065;</a>';
}

function dolphin_qb_stages(frm, ref){
  var d = frm.doc, esc = frappe.utils.escape_html;
  var atport = ['At Port','At Bannikoppa Station yard','Shipped','Sold'].indexOf(d.status) >= 0;
  var shipped = ['Shipped','Sold'].indexOf(d.status) >= 0;
  return [
    {k:'Quarried', dt:'', nm:'', sub:'In Stock', on:true},
    {k:'Quarry Insp', dt:'Quarry Inspection', nm:ref.qi, sub:ref.qi||'not yet', on:!!ref.qi},
    {k:'Buyer Insp', dt:'Buyer Inspection', nm:ref.bi, sub:(ref.bi||'not yet')+(ref.ebn?(' &#183; '+esc(ref.ebn)):''), on:!!ref.bi},
    {k:'Delivery Challan', dt:'Delivery Challan', nm:ref.dc, sub:ref.dc||'not yet', on:!!ref.dc},
    {k:'Port Arrival', dt:'Port Arrival', nm:ref.pa, sub:ref.pa||(atport?'at port':'not yet'), on:!!ref.pa||atport},
    {k:'Export Lot', dt:'Export Shipment Lot', nm:ref.esl, sub:ref.esl||'not yet', on:!!ref.esl},
    {k:'Shipping', dt:'Shipping Document', nm:ref.sd, sub:ref.sd||(shipped?'shipped':'not yet'), on:!!ref.sd||shipped}
  ];
}

function dolphin_qb_strip(frm, extra){
  try{
    var d = frm.doc, esc = frappe.utils.escape_html;
    var ref = dolphin_qb_refs(frm, extra);
    $(frm.wrapper).find('.dolphin-journey').remove();
    var stages = dolphin_qb_stages(frm, ref);
    var cells = stages.map(function(s, i){
      var col = s.on ? '#16304F' : '#e7ebf0', tc = s.on ? '#fff' : '#8a929c', bd = s.on ? '#D4A24A' : '#d3d9e0';
      var arrow = (i < stages.length-1) ? '<div style="align-self:center;color:#aab2bc;font-weight:700;padding:0 2px">&#8250;</div>' : '';
      return '<div style="flex:1;min-width:118px;background:'+col+';color:'+tc+';border-radius:8px;padding:8px 10px;border-left:3px solid '+bd+'"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.04em;opacity:.85">'+s.k+dolphin_qb_eye(s.dt, s.nm)+'</div><div style="font-size:12px;font-weight:600;margin-top:2px">'+(s.sub||'-')+'</div></div>' + arrow;
    }).join('');
    var SC = {'In Stock':'#6b7280','Buyer Marked':'#8a6d1f','In Delivery Challan':'#6b4a09','Dispatched/Transported':'#0c447c','At Port':'#e98a3c','At Bannikoppa Station yard':'#7a5cc0','Shipped':'#128666','Sold':'#128424'};
    var sc = SC[d.status] || '#333';
    var banner = '<div style="margin:2px 0 8px;font-size:13px"><b>Where is this block now?</b> <span style="background:'+sc+';color:#fff;border-radius:10px;padding:2px 10px;font-size:12px;margin-left:6px">'+esc(d.status||'-')+'</span> <a href="#" class="dj-full" style="margin-left:10px;font-size:12px">Block History &#8250;</a></div>';
    var wrap = $('<div class="dolphin-journey" style="margin:4px 0 8px"></div>').html(banner + '<div style="display:flex;gap:4px;flex-wrap:wrap;align-items:stretch">' + cells + '</div>');
    frm.dashboard.add_section(wrap);
    wrap.find('.dj-eye').on('click', function(e){ e.preventDefault(); var t=$(this); frappe.set_route('Form', t.attr('data-dt'), t.attr('data-nm')); });
    wrap.find('.dj-full').on('click', function(e){ e.preventDefault(); dolphin_qb_journey(frm); });
  }catch(e){ console.warn('dolphin strip', e); }
}

function dolphin_qb_journey(frm){
  var d = frm.doc, esc = frappe.utils.escape_html, nm = d.name;
  var dlg = new frappe.ui.Dialog({ title: 'Block History - ' + (d.block_number||nm), size: 'large', fields:[{fieldtype:'HTML', fieldname:'body'}] });
  var $b = dlg.fields_dict.body.$wrapper;
  $b.html('<div class="text-muted">Loading...</div>');
  dlg.show();
  Promise.all([
    frappe.db.get_list('Shipment Lot Block', {parent:"Export Shipment Lot", filters:{block:nm}, fields:['parent'], limit:1}),
    frappe.db.get_list('Shipping Block', {parent:"Shipping Document", filters:{block:nm}, fields:['parent'], limit:1}),
    frappe.db.get_list('Port Arrival Block', {parent:"Port Arrival", filters:{quarry_block:nm}, fields:['parent'], limit:1}),
    frappe.db.get_list('Comment', {filters:{reference_doctype:'Quarry Block', reference_name:nm, comment_type:['in',['Comment','Info','Edit','Label','Workflow']]}, fields:['content','comment_type','owner','creation'], order_by:'creation desc', limit:25})
  ]).then(function(r){
    var ref = dolphin_qb_refs(frm, {esl:(r[0][0]||{}).parent||'', sd:(r[1][0]||{}).parent||'', pa:(r[2][0]||{}).parent||''});
    var stages = dolphin_qb_stages(frm, ref);
    var rows = stages.map(function(s){
      var dot = s.on ? '#178a3a' : '#c4ccd6';
      var open = s.nm ? (' <a href="#" class="dj-eye" data-dt="'+s.dt+'" data-nm="'+esc(s.nm)+'" style="text-decoration:none">&#128065; open</a>') : '';
      return '<div style="display:flex;align-items:center;gap:10px;padding:7px 2px;border-bottom:1px solid #eef1f5"><span style="width:10px;height:10px;border-radius:50%;background:'+dot+';flex:none"></span><div style="width:130px;font-weight:600;font-size:12.5px">'+s.k+'</div><div style="flex:1;font-size:12.5px;color:#374151">'+(s.sub||'-')+'</div>'+open+'</div>';
    }).join('');
    var comments = (r[3]||[]);
    var clist = comments.length ? comments.map(function(c){
      var who = (c.owner||'').split('@')[0];
      var when = frappe.datetime.str_to_user ? frappe.datetime.str_to_user(c.creation) : c.creation;
      var txt = (c.content||'').replace(/<[^>]+>/g,'').trim();
      if(!txt) return '';
      return '<div style="padding:6px 2px;border-bottom:1px solid #f2f4f7;font-size:12px"><span style="color:#8a929c">'+esc(when)+' - '+esc(who)+'</span><div>'+esc(txt)+'</div></div>';
    }).join('') : '<div class="text-muted" style="font-size:12px">No remarks yet.</div>';
    var search = '<div style="display:flex;gap:6px;margin-bottom:12px"><input class="form-control dj-q" placeholder="Trace: block no, or BI / DC / SL / SHP / ARR / QI number..." style="flex:1"><button class="btn btn-default btn-sm dj-go">Go</button></div>';
    $b.html(search
      + '<div style="font-weight:600;margin:4px 0 4px;font-size:13px">Block History</div>' + rows
      + '<div style="font-weight:600;margin:14px 0 4px;font-size:13px">Remarks &amp; activity</div>' + clist);
    $b.find('.dj-eye').on('click', function(e){ e.preventDefault(); var t=$(this); dlg.hide(); frappe.set_route('Form', t.attr('data-dt'), t.attr('data-nm')); });
    function go(){ var v=($b.find('.dj-q').val()||'').trim(); if(v) dolphin_trace_go(v, dlg); }
    $b.find('.dj-go').on('click', go);
    $b.find('.dj-q').on('keydown', function(e){ if(e.which===13){ e.preventDefault(); go(); } });
  });
}

function dolphin_trace_go(v, dlg){
  var up = v.toUpperCase();
  function open(dt, nm){ if(dlg) dlg.hide(); frappe.set_route('Form', dt, nm); }
  function findOpen(dt, filters, label){
    frappe.db.get_list(dt, {filters:filters, fields:['name'], limit:1}).then(function(r){
      if(r && r[0]) open(dt, r[0].name); else frappe.show_alert({message:'No '+(label||dt)+' matched "'+v+'"', indicator:'orange'});
    });
  }
  if(up.indexOf('BI')===0){ findOpen('Buyer Inspection', [['name','like','%'+v+'%']], 'Buyer Inspection'); return; }
  if(up.indexOf('SHP')===0){ findOpen('Shipping Document', [['name','like','%'+v+'%']], 'Shipping Document'); return; }
  if(up.indexOf('SL')===0){ findOpen('Export Shipment Lot', [['name','like','%'+v+'%']], 'Export Shipment Lot'); return; }
  if(up.indexOf('ARR')===0){ findOpen('Port Arrival', [['name','like','%'+v+'%']], 'Port Arrival'); return; }
  if(up.indexOf('QI')===0 || up.indexOf('QINS')===0){ findOpen('Quarry Inspection', [['name','like','%'+v+'%']], 'Quarry Inspection'); return; }
  if(up.indexOf('DC')===0){
    frappe.db.get_list('Delivery Challan', {or_filters:[['name','like','%'+v+'%'],['delivery_challan_no','like','%'+v+'%']], fields:['name'], limit:1}).then(function(r){
      if(r && r[0]) open('Delivery Challan', r[0].name); else frappe.show_alert({message:'No Delivery Challan matched "'+v+'"', indicator:'orange'});
    });
    return;
  }
  frappe.db.get_list('Quarry Block', {filters:{block_number: v}, fields:['name'], limit:1}).then(function(r){
    if(r && r[0]){ open('Quarry Block', r[0].name); return; }
    frappe.db.get_list('Quarry Block', {filters:{export_block_no: v}, fields:['name'], limit:1}).then(function(r2){
      if(r2 && r2[0]) open('Quarry Block', r2[0].name); else frappe.show_alert({message:'No block "'+v+'" found', indicator:'orange'});
    });
  });
}

