      try{
        var journey = document.querySelector('.dolphin-journey');
        var bn = document.querySelector('[data-fieldname="block_number"]');
        var mainSection = bn ? bn.closest('.form-section') : null;
        var measCtl = document.querySelector('[data-fieldname="measurement_history_panel"]');
        if(journey && mainSection && mainSection.getAttribute('data-dj-placed')!=='1'){
          var body = mainSection.querySelector('.section-body') || mainSection;
          body.style.display='flex';
          body.style.flexWrap='nowrap';
          body.style.alignItems='flex-start';
          body.style.justifyContent='flex-start';
          body.style.gap='20px';
          var leftCol = body.querySelector('.form-column');
          if(leftCol){ leftCol.style.flex='1 1 0'; leftCol.style.minWidth='0'; leftCol.style.maxWidth='none'; leftCol.style.width='auto'; }
          var box=document.createElement('div'); box.className='dj-right-box';
