          box.appendChild(t); box.appendChild(journey); body.appendChild(box);
          mainSection.setAttribute('data-dj-placed','1');
        }
        if(measCtl && measCtl.getAttribute('data-dj-moved')!=='1'){
          var page = mainSection ? mainSection.closest('.form-page') : null;
          if(page){
            var wrap=document.createElement('div'); wrap.className='dj-meas-top';
            wrap.style.cssText='margin:4px 0 14px;padding:0;';
            page.insertBefore(wrap, page.firstChild);
            wrap.appendChild(measCtl);
            measCtl.setAttribute('data-dj-moved','1');
          }
        }
      }catch(e){ console.warn('reposition err', e); }
    }
    setTimeout(reposition, 350);
    setTimeout(reposition, 900);
    if(!frm.__djObserver){
      var host=document.querySelector('.form-layout')||document.body;
      frm.__djObserver=new MutationObserver(function(){ clearTimeout(frm.__djT); frm.__djT=setTimeout(reposition,150); });
      frm.__djObserver.observe(host,{childList:true,subtree:true});
    }
  }
});

function qb_checked(listview){
  var l = listview || window.cur_list;
  var names = [];
  try{ var r = l.get_checked_items(true); if(r && r.length) names = r.map(function(x){return (x&&x.name)?x.name:x;}); }catch(e){}
  if(!names.length){ try{ names = (l.get_checked_items()||[]).map(function(d){return (d&&d.name)?d.name:d;}).filter(Boolean); }catch(e){} }
  if(!names.length){ names = Array.prototype.slice.call(document.querySelectorAll('.list-row-checkbox:checked')).map(function(cb){ var c=cb.closest('.list-row-container')||cb.closest('.list-row'); return c?c.getAttribute('data-name'):null; }).filter(Boolean); }
  return names;
}
function qb_to(target, child){
  var names = qb_checked(window.cur_list);
  if(!names.length){ frappe.msgprint('Tick one or more blocks first.'); return; }
  if(target==='Delivery Challan' && names.length>12){ frappe.msgprint('A Delivery Challan takes 1–12 blocks; you ticked '+names.length+'. Reduce the selection.'); return; }
  try{var __sl=window.cur_list;if(__sl&&__sl.clear_checked_items){__sl.clear_checked_items();}else{Array.prototype.slice.call(document.querySelectorAll('.list-row-checkbox:checked')).forEach(function(cb){cb.checked=false;cb.dispatchEvent(new Event('change',{bubbles:true}));});}}catch(e){}
  frappe.new_doc(target).then(function(){
    cur_frm.clear_table(child);
    names.forEach(function(nm){ var r=cur_frm.add_child(child); frappe.model.set_value(r.doctype,r.name,'block',nm); });
    cur_frm.refresh_field(child);
    frappe.show_alert({message:names.length+' block(s) added to new '+target,indicator:'green'});
  });
}
