frappe.ui.form.on('Quarry Inspection', {
  refresh(frm){
    if(frm.is_new()) return;
    const allRows=(frm.doc.block_rows||[]).filter(function(r){return r.quarry_block_no;});
    const nums=Array.from(new Set(allRows.map(function(r){return String(r.quarry_block_no);})));

    frm.add_custom_button('Add to BI', function(){
      var bn=Array.from(new Set((frm.doc.block_rows||[]).map(function(r){return String(r.quarry_block_no||'').trim();}).filter(function(x){return x;})));
      if(!bn.length){ frappe.show_alert({message:'No blocks to add',indicator:'orange'}); return; }
      localStorage.setItem('dolphin_bi_from_qi', JSON.stringify({qi:frm.doc.name, nums:bn}));
      frappe.set_route('Form','Buyer Inspection','new');
    });

    frm.remove_custom_button('Push to Stock');
    frm.remove_custom_button('Update Stock');
    if(!allRows.length) return;
    frappe.db.get_list('Quarry Block',{filters:[['block_number','in',nums]],fields:['name','block_number'],limit:0}).then(function(ex){
      var byNum={}; (ex||[]).forEach(function(x){ byNum[String(x.block_number)]=x.name; });
      var pending=nums.filter(function(n){return !byNum[n];});
      var label=pending.length? 'Push to Stock' : 'Update Stock';
      var btn=frm.add_custom_button(label, async function(){
        if(frm.__qiPushing) return;
        frm.__qiPushing=true; btn.prop('disabled',true);
        frappe.dom.freeze(label+'...');
        const factor=frm.doc.tonnage_factor||2.7;
        var map={};
        try{ var ex2=await frappe.db.get_list('Quarry Block',{filters:[['block_number','in',nums]],fields:['name','block_number','length_gross','width_gross','height_gross'],limit:0}); (ex2||[]).forEach(function(x){map[String(x.block_number)]={name:x.name,l:x.length_gross,w:x.width_gross,h:x.height_gross};}); }catch(e){}
        var seen=new Set();
        let created=0,updated=0,unchanged=0,errs=0;
        for(const r of allRows){
          var bn=String(r.quarry_block_no);
          if(seen.has(bn)){continue;} seen.add(bn);
          var vol=(r.length_gross*r.width_gross*r.height_gross)/1e6;
          var dims={length_gross:r.length_gross,width_gross:r.width_gross,height_gross:r.height_gross,gross_volume:Math.round(vol*1e5)/1e5,gross_tonnage:Math.round(vol*factor*1000)/1000,pit:r.pit||null,gangman:r.gangman||null};
          try{
            if(map[bn]){
              var cur=map[bn];
              if(Number(cur.l)===Number(r.length_gross) && Number(cur.w)===Number(r.width_gross) && Number(cur.h)===Number(r.height_gross)){ unchanged++; }
              else { await frappe.db.set_value('Quarry Block', cur.name, dims); updated++; }
            }
            else { var d=Object.assign({doctype:'Quarry Block',block_number:bn,block_suffix:r.block_suffix||'',dmg_tonnage_factor:frm.doc.dmg_tonnage_factor||null,status:'In Stock',source_quarry_inspection:frm.doc.name}, dims); await frappe.db.insert(d); created++; }
          }catch(e){errs++;}
        }
        frappe.dom.unfreeze(); frm.__qiPushing=false;
        frappe.msgprint({title:'Stock Updated',indicator:'green',message:created+' created, '+updated+' updated, '+unchanged+' unchanged'+(errs?(', '+errs+' error(s)'):'')+'.'});
        frm.refresh();
      });
      btn.removeClass('btn-default').addClass('btn-primary').attr('title', pending.length? ('Create '+pending.length+' new, update changed') : 'Update only blocks whose measurements changed');
    });
  }
});

