window.dolphin_paste_blocks = function(frm, text, $row, startCol){
  startCol = startCol || 0;
  const fields = ['quarry_block_no','length_gross','width_gross','height_gross','gangman','pit'];
  const numeric = {length_gross:1, width_gross:1, height_gross:1};
  const lines = text.replace(/\r\n?/g,'\n').split('\n').filter(l => l.length>0);
  let startIdx = 0;
  const dn = $row.attr('data-name');
  const fidx = (frm.doc.block_rows||[]).findIndex(r => r.name === dn);
  if(fidx >= 0) startIdx = fidx;
  let count = 0;
  lines.forEach(function(line, i){
    const cols = line.split('\t');
    let row = frm.doc.block_rows[startIdx + i];
    if(!row) row = frm.add_child('block_rows');
    cols.forEach(function(val, ci){
      const fn = fields[startCol + ci];
      if(!fn) return;
      let v = val;
      if(v === undefined) return;
      v = String(v).trim();
      if(v === '') return;
      if(numeric[fn]) v = flt(v);
      frappe.model.set_value(row.doctype, row.name, fn, v);
    });
    count++;
  });
  frm.refresh_field('block_rows');
  frappe.show_alert({message: count + ' block rows pasted cleanly', indicator:'green'});
};

