function qi_calc_row(frm, cdt, cdn){
    let row = locals[cdt][cdn];
    let l = row.length_gross||0, w = row.width_gross||0, h = row.height_gross||0;
    let vol = Math.round((l*w*h)/1000000*100)/100;
    let factor = frm.doc.tonnage_factor||0;
    frappe.model.set_value(cdt,cdn,'gross_volume',vol);
    frappe.model.set_value(cdt,cdn,'gross_tonnage',Math.round(vol*factor*100)/100);
    qi_calc_totals(frm);
}
function qi_calc_totals(frm){
    let tv=0,tt=0,n=0;
    (frm.doc.block_rows||[]).forEach(r=>{tv+=r.gross_volume||0; tt+=r.gross_tonnage||0; n++;});
    frm.set_value('total_gross_volume',Math.round(tv*100)/100);
    frm.set_value('total_gross_tonnage',Math.round(tt*100)/100);
    frm.set_value('row_count',n);
}
frappe.ui.form.on('Quarry Inspection Block',{
    length_gross:qi_calc_row, width_gross:qi_calc_row, height_gross:qi_calc_row,
    block_rows_remove:function(frm){qi_calc_totals(frm);}
});
