        (frm.doc.block_rows||[]).forEach(r=>{
            let vol=Math.round(((r.length_gross||0)*(r.width_gross||0)*(r.height_gross||0))/1000000*100)/100;
            let factor=frm.doc.tonnage_factor||0;
            frappe.model.set_value(r.doctype,r.name,'gross_volume',vol);
            frappe.model.set_value(r.doctype,r.name,'gross_tonnage',Math.round(vol*factor*100)/100);
