window.dolphin_block_totals = function(frm){
  try {
    const grid = frm.fields_dict.block_rows && frm.fields_dict.block_rows.grid;
    if(!grid || !grid.wrapper) return;
    const wrap = grid.wrapper[0];
    setTimeout(function(){
      const head = wrap.querySelector('.grid-heading-row');
      const rowsC = wrap.querySelector('.grid-body .rows');
      if(!head || !rowsC) return;
      const existing = wrap.querySelector('.dolphin-totals-row');
      if(existing) existing.remove();
      const sums = {length_gross:0,width_gross:0,height_gross:0,gross_volume:0,gross_tonnage:0};
      (frm.doc.block_rows||[]).forEach(function(r){ Object.keys(sums).forEach(function(f){ sums[f]+= (parseFloat(r[f])||0); }); });
      const count = (frm.doc.block_rows||[]).length;
      const tr = head.cloneNode(true);
      tr.classList.add('dolphin-totals-row');
      tr.style.fontWeight='700';
      tr.style.background='#eef1f5';
      tr.style.borderTop='2px solid #0F2540';
      tr.querySelectorAll('input').forEach(function(i){ i.remove(); });
      Array.from(tr.querySelectorAll('.grid-static-col')).forEach(function(c){
        const fn = c.getAttribute('data-fieldname');
        c.innerHTML=''; c.style.color='#0F2540';
        if(fn==='quarry_block_no'){ c.textContent='TOTAL ('+count+')'; }
        else if(fn==='gross_volume'){ c.textContent = (Math.round(sums.gross_volume*1000)/1000).toFixed(3); }
        else if(fn==='gross_tonnage'){ c.textContent = (Math.round(sums.gross_tonnage*100)/100).toFixed(2); }
      });
      rowsC.appendChild(tr);
    }, 200);
  } catch(e){ console.error('dolphin_block_totals', e); }
};

