  function get(){try{return JSON.parse(localStorage.getItem(KEY)||"[]");}catch(e){return [];}}
  function set(a){localStorage.setItem(KEY,JSON.stringify(a));}
  function add(rows){var c=get();var h={};c.forEach(function(x){h[x.block]=1;});var n=0;rows.forEach(function(r){if(r.block&&!h[r.block]){c.push(r);h[r.block]=1;n++;}});set(c);return n;}
  function rem(b){set(get().filter(function(x){return String(x.block)!=String(b);}));}
  function clr(){set([]);}
  function f(v,d){return (v==null?0:Number(v)).toFixed(d||2);}
  function dccode(dt){var p=String(dt).split("-");var y=+p[0],m=+p[1],d=+p[2];return String.fromCharCode(64+m)+String.fromCharCode(65+Math.floor(d/10))+String.fromCharCode(65+(d%10))+String.fromCharCode(65+(y-2020));}
  function nextSerial(){return frappe.db.get_list("Delivery Challan",{fields:["dc_no"],limit:0}).then(function(l){var mx=0;l.forEach(function(x){var m=/^DC-[A-Z]{4}-(\d+)$/.exec(x.dc_no||"");if(m){var n=parseInt(m[1]);if(n>mx)mx=n;}});return ("000"+(mx+1)).slice(-3);});}
  function openCart(){
    var c=get();var tv=0,gv=0;c.forEach(function(x){tv+=(x.gross_tonnage||0);gv+=(x.gross_volume||0);});
    var d=new frappe.ui.Dialog({title:"DC Cart - "+c.length+" blocks",size:"large"});
    var rows=c.map(function(x,i){return "<tr><td>"+(i+1)+"</td><td>"+x.block+"</td><td>"+(x.grade||"")+"</td><td>"+(x.source||"")+"</td><td style='text-align:right'>"+f(x.gross_volume,3)+"</td><td style='text-align:right'>"+f(x.gross_tonnage,2)+"</td><td><a class='di-rm' data-b='"+x.block+"' style='color:#c0392b;cursor:pointer'>&#10005;</a></td></tr>";}).join("");
    if(!c.length){rows="<tr><td colspan='7' style='text-align:center;color:#888;padding:14px'>Cart empty. Tick blocks on an inspection or the Quarry Block list, then Add to DC Cart.</td></tr>";}
    d.$body.html("<div style='max-height:330px;overflow:auto'><table class='table table-bordered' style='font-size:12px'><thead><tr><th>#</th><th>Block</th><th>Grade</th><th>Source IR</th><th style='text-align:right'>Vol</th><th style='text-align:right'>MT</th><th></th></tr></thead><tbody>"+rows+"</tbody></table></div><div style='text-align:right;font-weight:700;color:#0F2540;margin-top:6px'>Total: "+c.length+" blocks - "+f(gv,3)+" CBM - "+f(tv,2)+" MT</div>");
    d.$body.find(".di-rm").on("click",function(){rem($(this).data("b"));d.hide();openCart();});
    if(c.length){
      d.set_primary_action("Build Delivery Challan",function(){d.hide();buildDC();});
      var cb=$("<button class='btn btn-sm btn-default' style='margin-left:8px'>Clear all</button>");
      cb.on("click",function(){frappe.confirm("Clear the whole cart?",function(){clr();d.hide();frappe.show_alert("Cart cleared");});});
      d.$wrapper.find(".modal-header").append(cb);
    }
    d.show();
  }
  function buildDC(){
    var c=get();if(!c.length){frappe.msgprint("Cart is empty");return;}
    var tv=0,gv=0;c.forEach(function(x){tv+=(x.gross_tonnage||0);gv+=(x.gross_volume||0);});
    var bd=new frappe.ui.Dialog({title:"Build Delivery Challan ("+c.length+" blocks)",fields:[
      {fieldname:"export_consignee",label:"Export Consignee",fieldtype:"Link",options:"Export Consignee",depends_on:"eval:doc.sale_type=='Export'",mandatory_depends_on:"eval:doc.sale_type=='Export'"},
      {fieldname:"local_consignee",label:"Local Consignee",fieldtype:"Link",options:"Local Consignee",depends_on:"eval:doc.sale_type!='Export'",mandatory_depends_on:"eval:doc.sale_type!='Export'"},
      {fieldname:"sale_type",label:"Sale Type",fieldtype:"Select",options:["Export","Local"],default:"Export",reqd:1},
      {fieldname:"dc_date",label:"Date",fieldtype:"Date",default:frappe.datetime.get_today(),reqd:1},
      {fieldname:"note",fieldtype:"HTML",options:"<div style='color:#6b7a90;font-size:12px;margin-top:4px'>Challan No is auto-generated from the date (e.g. DC-FBDG-001).</div>"}
    ],primary_action_label:"Create",primary_action:function(v){
      nextSerial().then(function(serial){
        var dcno="DC-"+dccode(v.dc_date)+"-"+serial;
        var rows=c.map(function(x){return {block:x.block,grade:x.grade,source_inspection:x.source,length_gross:x.length_gross,width_gross:x.width_gross,height_gross:x.height_gross,gross_volume:x.gross_volume,gross_tonnage:x.gross_tonnage};});
        frappe.db.insert({doctype:"Delivery Challan",dc_no:dcno,dc_date:v.dc_date,sale_type:v.sale_type,consignee:(v.sale_type==='Export'?undefined:v.local_consignee),export_consignee:(v.sale_type==='Export'?v.export_consignee:undefined),block_count:c.length,total_volume:gv,total_tonnage:tv,dc_block_rows:rows}).then(function(doc){clr();bd.hide();frappe.show_alert({message:"Delivery Challan "+doc.name+" created",indicator:"green"});frappe.set_route("Form","Delivery Challan",doc.name);}).catch(function(e){frappe.msgprint("Could not create DC. Check Buyer / duplicate number.");});
      });
    }});
    bd.show();
  }
  return {get:get,add:add,rem:rem,clr:clr,openCart:openCart,buildDC:buildDC,count:function(){return get().length;}};
})();}
