// Dolphin: two-way Gangman <-> Pit autofill (source: Pit.gangman)
frappe.provide('dolphin');
dolphin.pit_map_loaded = false;
dolphin.P2G = {};
dolphin.G2P = {};
dolphin.load_pit_map = function(cb){
  frappe.db.get_list('Pit', {fields:['name','gangman'], limit:0}).then(function(rows){
    var P2G={}, G2P={};
    (rows||[]).forEach(function(r){
      if(r.gangman){
        P2G[String(r.name)] = r.gangman;
        (G2P[r.gangman] = G2P[r.gangman] || []).push(String(r.name));
      }
    });
    dolphin.P2G = P2G; dolphin.G2P = G2P; dolphin.pit_map_loaded = true;
    if(cb) cb();
  });
};
frappe.ui.form.on('Quarry Inspection', {
  setup: function(frm){
    dolphin.load_pit_map();
    frm.set_query('pit','block_rows', function(doc, cdt, cdn){
      var row = locals[cdt][cdn];
      if(row && row.gangman && dolphin.G2P[row.gangman]){
        return {filters:{name:['in', dolphin.G2P[row.gangman]]}};
      }
      return {};
    });
  },
  onload: function(frm){ if(!dolphin.pit_map_loaded) dolphin.load_pit_map(); },
  refresh: function(frm){ if(!dolphin.pit_map_loaded) dolphin.load_pit_map(); }
});
frappe.ui.form.on('Quarry Inspection Block', {
  gangman: function(frm, cdt, cdn){
    var row = locals[cdt][cdn];
    if(!row.gangman) return;
    var pits = dolphin.G2P[row.gangman] || [];
    if(pits.length===1 && row.pit!==pits[0]){ frappe.model.set_value(cdt, cdn, 'pit', pits[0]); }
  },
  pit: function(frm, cdt, cdn){
    var row = locals[cdt][cdn];
    if(!row.pit) return;
    var g = dolphin.P2G[String(row.pit)];
    if(g && row.gangman!==g){ frappe.model.set_value(cdt, cdn, 'gangman', g); }
  }
});

