// Dolphin: per-row DMG factor from Pit + Gross Tonnage + L/W/H 1-999 validation
frappe.provide('dolphin');
dolphin.pitfac = dolphin.pitfac || {}; dolphin.pitfac_loaded = false;
dolphin.load_pitfac = function(cb){
  frappe.db.get_list('Pit',{fields:['name','specific_gravity'],limit:0}).then(function(rows){
    var m={}; (rows||[]).forEach(function(r){ m[String(r.name)] = flt(r.specific_gravity); });
    dolphin.pitfac = m; dolphin.pitfac_loaded = true; if(cb) cb();
  });
};
window.dolphin_dim_ok = function(frm, cdt, cdn, field){
  var row = locals[cdt][cdn]; var v = row[field];
  if(v!==null && v!=='' && (flt(v) < 1 || flt(v) > 999)){
    frappe.show_alert({message: '⚠ ' + field.replace('_gross','').toUpperCase() + ' must be 1-999 cm (3 digits). Cleared ' + v + ' — re-enter.', indicator:'red'}, 6);
    frappe.model.set_value(cdt, cdn, field, null);
    return false;
  }
  return true;
};
window.dolphin_recalc_ton = function(frm){
  setTimeout(function(){
    var tv=0, tt=0;
    (frm.doc.block_rows||[]).forEach(function(r){
      var vol = flt(r.length_gross)*flt(r.width_gross)*flt(r.height_gross)/1000000; vol = Math.round(vol*10000)/10000;
      var ton = Math.round(vol*flt(r.dmg_factor)*100)/100;
      if(r.gross_volume !== vol) frappe.model.set_value(r.doctype, r.name, 'gross_volume', vol);
      if(r.gross_tonnage !== ton) frappe.model.set_value(r.doctype, r.name, 'gross_tonnage', ton);
      tv += vol; tt += ton;
    });
    frm.set_value('total_gross_volume', Math.round(tv*1000)/1000);
    frm.set_value('total_gross_tonnage', Math.round(tt*100)/100);
    frm.refresh_field('block_rows');
  }, 150);
};
window.dolphin_set_factor = function(frm, cdt, cdn){
  var row = locals[cdt][cdn];
  if(!dolphin.pitfac_loaded){ dolphin.load_pitfac(function(){ window.dolphin_set_factor(frm, cdt, cdn); }); return; }
  if(row.pit){ var fac = dolphin.pitfac[String(row.pit)] || 0; if(flt(row.dmg_factor) !== fac) frappe.model.set_value(cdt, cdn, 'dmg_factor', fac); }
  window.dolphin_recalc_ton(frm);
};
frappe.ui.form.on('Quarry Inspection', {
  onload: function(frm){ dolphin.load_pitfac(); },
  refresh: function(frm){ if(!dolphin.pitfac_loaded) dolphin.load_pitfac(function(){ window.dolphin_recalc_ton(frm); }); }
});
frappe.ui.form.on('Quarry Inspection Block', {
  pit: function(frm, cdt, cdn){ window.dolphin_set_factor(frm, cdt, cdn); },
  dmg_factor: function(frm, cdt, cdn){
    var row = locals[cdt][cdn];
    if(row.pit && dolphin.pitfac_loaded){
      var def = dolphin.pitfac[String(row.pit)] || 0;
      if(row.dmg_factor!==null && row.dmg_factor!=='' && flt(row.dmg_factor) !== def){
        frappe.show_alert({message: '⚠ DMG factor OVERRIDDEN for Block ' + (row.quarry_block_no || ('row '+row.idx)) + ': ' + flt(row.dmg_factor) + ' (Pit ' + row.pit + ' default is ' + def + ')', indicator:'orange'}, 7);
      }
    }
    window.dolphin_recalc_ton(frm);
  },
  length_gross: function(frm, cdt, cdn){ if(window.dolphin_dim_ok(frm,cdt,cdn,'length_gross')) window.dolphin_recalc_ton(frm); },
  width_gross: function(frm, cdt, cdn){ if(window.dolphin_dim_ok(frm,cdt,cdn,'width_gross')) window.dolphin_recalc_ton(frm); },
  height_gross: function(frm, cdt, cdn){ if(window.dolphin_dim_ok(frm,cdt,cdn,'height_gross')) window.dolphin_recalc_ton(frm); },
  block_rows_remove: function(frm){ window.dolphin_recalc_ton(frm); }
});

frappe.ui.form.on('Quarry Inspection', {
  refresh: function(frm){ dolphin_prime_pits(frm); }
});
frappe.ui.form.on('Quarry Inspection Block', {
  gangman: function(frm, cdt, cdn){
    var row=locals[cdt][cdn];
    if(row.gangman){
      frappe.db.get_doc('Gangman', row.gangman).then(function(g){
        window.__dolphinPits=window.__dolphinPits||{};
        window.__dolphinPits[row.gangman]=(g.pits||[]).map(function(p){return p.pit;});
        frappe.model.set_value(cdt,cdn,'pit','');
      });
    }
  }
});
function dolphin_prime_pits(frm){
  window.__dolphinPits=window.__dolphinPits||{};
  (frm.doc.block_rows||[]).forEach(function(row){
    if(row.gangman && !window.__dolphinPits[row.gangman]){
      frappe.db.get_doc('Gangman', row.gangman).then(function(g){ window.__dolphinPits[row.gangman]=(g.pits||[]).map(function(p){return p.pit;}); });
    }
  });
  frm.set_query('pit','block_rows', function(doc, cdt, cdn){
    var row=locals[cdt][cdn];
    var pits=(window.__dolphinPits||{})[row.gangman];
    if(pits && pits.length){ return {filters:{name:['in',pits]}}; }
    return {};
  });
}

