    w.$wrapper.html('<div style="padding:8px;color:#888">Loading activity...</div>');
    var ids=(frm.doc.block_rows||[]).map(function(r){return r.quarry_block_no;}).filter(Boolean);
    var qbP = ids.length? frappe.db.get_list('Quarry Block',{filters:[['block_number','in',ids]],fields:['name','block_number'],limit:0}).catch(function(){return [];}) : Promise.resolve([]);
    qbP.then(function(qbs){
      var names=(qbs||[]).map(function(x){return x.name;});
      var num={}; (qbs||[]).forEach(function(x){num[String(x.name)]=x.block_number;});
      var histP = (canHist && names.length)? frappe.db.get_list('Block Measurement History',{filters:[['parenttype','=','Quarry Block'],['parent','in',names]],fields:['parent','measured_on','event_type','length_gross','width_gross','height_gross','gross_volume'],order_by:'measured_on desc',limit:40}).catch(function(){return [];}) : Promise.resolve([]);
      var verP = canVer? frappe.db.get_list('Version',{filters:[['ref_doctype','=',frm.doctype],['docname','=',frm.doc.name]],fields:['owner','creation','data'],order_by:'creation desc',limit:20}).catch(function(){return [];}) : Promise.resolve([]);
      Promise.all([verP,histP]).then(function(res){
        var vers=res[0]||[], hist=res[1]||[];
        function isInit(v){ return v===null||v===undefined||v===''||v===0||v==='0'; }
        function fmt(v){ return (v===null||v===undefined||v==='')?'(blank)':v; }
