function sl_allow_side(L,W,H,target){ if(L<=0||W<=0||H<=0) return 0; var gv=L*W*H/1e6; if(target>=gv) return 0; var lo=0, hi=Math.min(L,W,H)/2; if(target<=0) return Math.round(hi*100)/100; for(var i=0;i<60;i++){ var a=(lo+hi)/2; var v=Math.max(L-2*a,0)*Math.max(W-2*a,0)*Math.max(H-2*a,0)/1e6; if(v>target){ lo=a; } else { hi=a; } } return Math.round((lo+hi)/2*100)/100; }
function sl_classify(frm,row){
  if(row.is_unshaped){ row.size_class='—'; return; }
  var L=row.length_gross||0,W=row.width_gross||0,H=row.height_gross||0;
  var aL=frm.doc.a_min_length||0,aW=frm.doc.a_min_width||0,aH=frm.doc.a_min_height||0;
  var bL=frm.doc.b_min_length||0,bW=frm.doc.b_min_width||0,bH=frm.doc.b_min_height||0;
  if(L>=aL&&W>=aW&&H>=aH) row.size_class='A';
