  var dmg=frm.doc.dmg_factor||2.7, sf=frm.doc.agreed_factor||(frm.doc.dmg_factor||2.7), price=frm.doc.price_per_cbm||0, cost=frm.doc.cost_per_cbm||0, fx=frm.doc.fx_rate||0;
  row.gross_volume=Math.round(L*W*H/1e6*1e4)/1e4;
  row.gross_tonnage=Math.round(row.gross_volume*dmg*1000)/1000;
  sl_classify(frm,row);
  var _a=(frm.doc.apply_allowance&&(frm.doc.allowance_cm||0)>0)?frm.doc.allowance_cm:0; var _nv=_a>0?(Math.max(0,L-_a)*Math.max(0,W-_a)*Math.max(0,H-_a))/1e6:row.gross_volume; row.agreed_tonnage=Math.round(_nv*dmg*1000)/1000; var saleTon=row.agreed_tonnage||0;
  row.sale_cbm=sf>0?Math.round(saleTon/sf*1e4)/1e4:0;
  row.implied_allowance_cm=Math.round((row.gross_volume-row.sale_cbm)*1e4)/1e4;
  row.allowance_side_cm=sl_allow_side(L,W,H,row.sale_cbm);
  row.net_volume=row.sale_cbm;
  row.net_tonnage=Math.round(row.sale_cbm*dmg*1000)/1000;
  row.tonnage_diff=Math.round((row.gross_tonnage-row.net_tonnage)*1000)/1000;
  row.sale_value=Math.round(row.sale_cbm*price*100)/100;
  row.value_diff=Math.round((row.gross_volume-row.sale_cbm)*price*100)/100;
  row.cost_value=Math.round(row.sale_cbm*cost*100)/100;
  row.profit=Math.round((row.sale_value-(fx>0?row.cost_value/fx:0))*100)/100;
}
function sl_recalc_all(frm){ (frm.doc.block_rows||[]).forEach(function(r){ sl_calc_row(frm,r); }); frm.refresh_field('block_rows'); sl_recalc_totals(frm); }
function sl_recalc_totals(frm){
  var rows=frm.doc.block_rows||[], ton=0,cbm=0,valUSD=0,costINR=0,gcbm=0,gton=0,freeCbm=0,vdiff=0;
  rows.forEach(function(r){ ton+=r.agreed_tonnage||0; cbm+=r.sale_cbm||0; valUSD+=r.sale_value||0; costINR+=r.cost_value||0; gcbm+=r.gross_volume||0; gton+=r.gross_tonnage||0; freeCbm+=r.implied_allowance_cm||0; vdiff+=r.value_diff||0; });
  var fx=frm.doc.fx_rate||0; var revINR=Math.round(valUSD*fx*100)/100, costUSD=fx>0?costINR/fx:0;
  frm.set_value('block_count',rows.length);
  frm.set_value('total_gross_cbm',Math.round(gcbm*1e4)/1e4);
  frm.set_value('total_gross_tonnage',Math.round(gton*1000)/1000);
  frm.set_value('total_agreed_tonnage',Math.round(ton*1000)/1000);
  frm.set_value('total_sale_cbm',Math.round(cbm*1e4)/1e4);
  frm.set_value('total_free_allowance_cbm',Math.round(freeCbm*1e4)/1e4);
  frm.set_value('total_value_diff',Math.round(vdiff*100)/100);
  frm.set_value('total_sale_value',Math.round(valUSD*100)/100);
  frm.set_value('total_revenue_inr',revINR);
  frm.set_value('total_cost_inr',Math.round(costINR*100)/100);
  frm.set_value('total_profit_usd',Math.round((valUSD-costUSD)*100)/100);
  frm.set_value('total_profit_inr',Math.round((revINR-costINR)*100)/100);
  frm.set_value('margin_pct',valUSD>0?Math.round((valUSD-costUSD)/valUSD*10000)/100:0);
}
