function dlp_saleable(frm){
  var dmg = frm.doc.dmg_factor || 2.7;
  if(!frm.doc.agreed_factor){ frm.doc.agreed_factor = dmg; }
  var useAllow = (frm.doc.apply_allowance && (frm.doc.allowance_cm||0) > 0);
  var a = useAllow ? frm.doc.allowance_cm : 0;
  (frm.doc.block_rows || []).forEach(function(r){
    if(r.is_unshaped){ return; }
    var L = r.length_gross||0, W = r.width_gross||0, H = r.height_gross||0;
    var gv = Math.round(L*W*H/1e6*1e4)/1e4;
    var netVol = a>0 ? (Math.max(0,L-a)*Math.max(0,W-a)*Math.max(0,H-a))/1e6 : gv;
    netVol = Math.round(netVol*1e4)/1e4;
    r.agreed_tonnage = Math.round(netVol*dmg*1000)/1000;
  });
  if(window.sl_recalc_all){ try{ sl_recalc_all(frm); }catch(e){ console.log('dlp recalc',e); } }
  frm.refresh_field('block_rows');
}
