      if(m.granite_quality_grade && !row.grade) frappe.model.set_value(cdt,cdn,'grade', m.granite_quality_grade);
      setTimeout(function(){ recalcS(frm); }, 300);
    });
  },
  net_volume: function(frm){ recalcS(frm); },
  net_tonnage: function(frm){ recalcS(frm); },
  blocks_remove: function(frm){ recalcS(frm); }
});
function recalcS(frm){
  var rows=frm.doc.blocks||[]; var cbm=0,mt=0;
  rows.forEach(function(r){ cbm+=(r.net_volume||0); mt+=(r.net_tonnage||0); });
  frm.set_value('block_count', rows.length);
  frm.set_value('total_cbm', Math.round(cbm*1000)/1000);
  frm.set_value('total_net_tonnage', Math.round(mt*100)/100);
}

