frappe.ui.form.on('Shipping Block', {
  block: function(frm, cdt, cdn){
    var row = locals[cdt][cdn];
    if(!row.block) return;
    frappe.db.get_value('Quarry Block', row.block, ['length_gross','width_gross','height_gross','granite_quality_grade','block_number']).then(function(r){
      var d = r.message || {};
      if(d.length_gross!=null) frappe.model.set_value(cdt,cdn,'length', d.length_gross);
      if(d.width_gross!=null) frappe.model.set_value(cdt,cdn,'width', d.width_gross);
      if(d.height_gross!=null) frappe.model.set_value(cdt,cdn,'height', d.height_gross);
      if(d.granite_quality_grade) frappe.model.set_value(cdt,cdn,'grade', d.granite_quality_grade);
      if(d.block_number && !row.block_no) frappe.model.set_value(cdt,cdn,'block_no', d.block_number);
      var cbm = (flt(d.length_gross)*flt(d.width_gross)*flt(d.height_gross))/1e6;
      var mt = cbm*2.6;
      frappe.model.set_value(cdt,cdn,'net_volume', Math.round(cbm*1000)/1000);
      frappe.model.set_value(cdt,cdn,'net_tonnage', Math.round(mt*1000)/1000);
      frappe.model.set_value(cdt,cdn,'net_kgs', Math.round(mt*1000));
    });
  }
});

frappe.ui.form.on('Shipping Document', {
  refresh: function(frm) {
    if (frm.is_new()) return;
    // Take over 'Mark Shipped' ordering: drop the early one, re-add it last below.
    try { frm.remove_custom_button('Mark Shipped'); } catch(e){}
    function withLot(cb){
      if (frm.doc.source_lot) return cb(frm.doc.source_lot);
      frappe.db.get_value('Export Shipment Lot', {shipping_document: frm.doc.name}, 'name').then(function(r){ cb(r && r.message && r.message.name); });
    }
    function printUrl(fmt){ return '/printview?doctype=Shipping%20Document&name=' + encodeURIComponent(frm.doc.name) + '&format=' + encodeURIComponent(fmt) + '&no_letterhead=0&trigger_print=0'; }
    function pdfUrl(fmt){ return '/api/method/frappe.utils.print_format.download_pdf?doctype=Shipping%20Document&name=' + encodeURIComponent(frm.doc.name) + '&format=' + encodeURIComponent(fmt) + '&no_letterhead=0'; }
    // In-page preview modal; 'Full view' opens a new tab, 'Download PDF' downloads.
    function previewModal(fmt, title){
      var d = new frappe.ui.Dialog({ title: title, size: 'extra-large', primary_action_label: 'Download PDF', primary_action: function(){ window.open(pdfUrl(fmt), '_blank'); } });
      d.set_secondary_action_label('Full view (new tab)');
      d.set_secondary_action(function(){ window.open(printUrl(fmt), '_blank'); });
      d.$body.html('<iframe src="' + printUrl(fmt) + '" style="width:100%;height:72vh;border:0;background:#fff;border-radius:6px"></iframe>');
      d.show(); d.$wrapper.find('.modal-dialog').css('max-width', '1050px');
    }
    function pdf(fmt){ window.open(pdfUrl(fmt), '_blank'); }
    function esc(v){ return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;'); }
    function xls(){
      var rows = frm.doc.blocks || [];
      if (!rows.length) { frappe.msgprint('No blocks to export.'); return; }
      var head = ['#','Block No','Grade','Net Volume (CBM)','Net MT','Container'];
      var tv = 0, tt = 0;
      var body = rows.map(function(r,i){ tv += (r.net_volume||0); tt += (r.net_tonnage||0); return [i+1, r.block_no||r.block||'', r.grade||'', r.net_volume||'', r.net_tonnage||'', r.container||'']; });
      var thead = '<tr>' + head.map(function(h){ return '<th style="background:#0F2540;color:#fff">' + esc(h) + '</th>'; }).join('') + '</tr>';
      var tbody = body.map(function(row){ return '<tr>' + row.map(function(c){ return '<td>' + esc(c) + '</td>'; }).join('') + '</tr>'; }).join('');
      var total = '<tr><td colspan="3"><b>Total (' + rows.length + ' blocks)</b></td><td><b>' + tv.toFixed(3) + '</b></td><td><b>' + tt.toFixed(3) + '</b></td><td></td></tr>';
      var caption = 'Shipping Document ' + frm.doc.name + '  -  ' + esc(frm.doc.export_consignee||'');
      var htmlDoc = '<html><head><meta charset="utf-8"></head><body><h3>' + esc(caption) + '</h3><table border="1" cellspacing="0" cellpadding="4"><thead>' + thead + '</thead><tbody>' + tbody + total + '</tbody></table></body></html>';
      var blob = new Blob([htmlDoc], { type: 'application/vnd.ms-excel' });
      var a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = frm.doc.name + ' - block list.xls'; document.body.appendChild(a); a.click(); setTimeout(function(){ a.remove(); }, 500);
    }
    frm.add_custom_button('Preview Packing List', function(){ previewModal('DI Packing List', 'Packing List'); });
    frm.add_custom_button('Download PDF - Packing List', function(){ pdf('DI Packing List'); });
    frm.add_custom_button('Preview Invoice', function(){ previewModal('DI Commercial Invoice', 'Commercial Invoice'); });
    frm.add_custom_button('Download PDF - Invoice', function(){ pdf('DI Commercial Invoice'); });
    frm.add_custom_button('Download Excel (blocks)', function(){ xls(); });
    frm.add_custom_button('Unlink SD - return ALL blocks', function(){
      withLot(function(lot){ if (!lot) { frappe.msgprint('No source lot.'); return; }
        frappe.confirm('Return <b>every</b> block to lot ' + lot + ' as ready-for-export and unlink this Shipping Document?', function(){
          frappe.call({ method: 'dolphin_theme.api_arrivals.return_blocks_from_lot', args: { lot: lot }, freeze: true }).then(function(r){ if (r && r.message) { frappe.show_alert({ message: 'Returned ' + r.message.returned + ' blocks', indicator: 'orange' }); frm.reload_doc(); } });
        });
      });
    });
    frm.add_custom_button('Return selected blocks', function(){
      var rows = frm.doc.blocks || [];
      if (!rows.length) { frappe.msgprint('This Shipping Document has no blocks.'); return; }
      var d = new frappe.ui.Dialog({ title: 'Return selected blocks', size: 'small', fields: [{ fieldtype: 'HTML', fieldname: 'html' }], primary_action_label: 'Return ticked blocks', primary_action: function(){
        var picked = []; d.$wrapper.find('input.dblk:checked').each(function(){ picked.push($(this).val()); });
        if (!picked.length) { frappe.msgprint('Tick at least one block.'); return; }
        withLot(function(lot){ if (!lot) { frappe.msgprint('No source lot.'); return; }
          frappe.call({ method: 'dolphin_theme.api_arrivals.return_blocks_from_lot', args: { lot: lot, blocks: picked }, freeze: true }).then(function(r){ if (r && r.message) { frappe.show_alert({ message: 'Returned ' + r.message.returned + ' block(s)', indicator: 'orange' }); d.hide(); frm.reload_doc(); } });
        });
      } });
      var html = rows.map(function(r){ var v = r.block || r.block_no; return '<label style="display:block;padding:5px 2px;border-bottom:1px solid #eee"><input type="checkbox" class="dblk" value="' + v + '" style="margin-right:8px">' + (r.block_no || r.block) + ' - ' + (r.grade || '-') + '</label>'; }).join('');
      d.fields_dict.html.$wrapper.html('<div style="max-height:340px;overflow:auto">' + html + '</div>'); d.show();
    });
    // --- Rarely-used status actions, added LAST so they sit at the bottom ---
    frm.add_custom_button('Mark Shipped', function(){
      var names = (frm.doc.blocks||[]).map(function(r){ return r.block; }).filter(Boolean);
      if (!names.length) { frappe.msgprint('No linked blocks.'); return; }
      frappe.confirm('Mark ' + names.length + ' block(s) as Shipped?', function(){
        var chain = Promise.resolve();
        names.forEach(function(nm){ chain = chain.then(function(){ return frappe.call({ method:'frappe.client.set_value', args:{ doctype:'Quarry Block', name:nm, fieldname:{ status:'Shipped' } } }); }); });
        chain.then(function(){ frappe.show_alert({ message: names.length + ' block(s) marked Shipped', indicator:'green' }); });
      });
    });
    frm.add_custom_button('Mark as Exported', function(){
      if (!frm.doc.bl_no) { frappe.msgprint('Enter the Bill of Lading number (from the port) first.'); return; }
      withLot(function(lot){ if (!lot) { frappe.msgprint('No source lot linked.'); return; }
        frappe.confirm('Mark lot <b>' + lot + '</b> and its blocks as <b>Exported (Shipped)</b>?', function(){
          frappe.call({ method: 'dolphin_theme.api_arrivals.mark_lot_exported', args: { lot: lot }, freeze: true, freeze_message: 'Marking as exported...' }).then(function(r){ if (r && r.message) frappe.show_alert({ message: 'Exported - ' + r.message.blocks_marked + ' blocks Shipped', indicator: 'green' }); });
        });
      });
    });
    // --- Light de-dupe guard (removes any repeated harvested items) ---
    function dedupe(){
      ['.di-ab-menu', '.custom-actions'].forEach(function(sel){
        document.querySelectorAll(sel).forEach(function(menu){
          var seen = {};
          Array.prototype.slice.call(menu.children).forEach(function(ch){ var t = (ch.textContent||'').replace(/\s+/g,' ').trim(); if (!t) return; if (seen[t]) { if (ch.parentNode) ch.parentNode.removeChild(ch); } else { seen[t] = 1; } });
        });
      });
    }
    setTimeout(dedupe, 300); setTimeout(dedupe, 900);
  }
});

