frappe.ui.form.on('Shipping Document', {
  unit_rate: function(f){di_c(f);}, rate_basis: function(f){di_c(f);}, tax_treatment: function(f){di_c(f);},
  tax_rate: function(f){di_a(f);}, total_cbm: function(f){di_a(f);}, total_net_tonnage: function(f){di_a(f);}, exchange_rate: function(f){di_a(f);},
  refresh: function(f){di_c(f);}
});
function di_c(frm){
  var rate;
  if(frm.doc.tax_treatment==='Domestic 5% GST') rate=5;
  else if(frm.doc.tax_treatment==='Export with IGST') rate=frm.doc.tax_rate||0;
  else rate=0;
  if((frm.doc.tax_rate||0)!==rate && frm.doc.tax_treatment!=='Export with IGST'){ frm.set_value('tax_rate', rate); }
  di_a(frm);
}
function di_a(frm){
  var kgs=Math.round((frm.doc.total_net_tonnage||0)*1000);
  if((frm.doc.total_net_kgs||0)!==kgs) frm.set_value('total_net_kgs', kgs);
  var b=frm.doc.rate_basis;
  var qty = b==='Per Tonne' ? (frm.doc.total_net_tonnage||0) : (b==='Per CBM' ? (frm.doc.total_cbm||0) : kgs);
  var val=(frm.doc.unit_rate||0)*qty;
  var tax=val*(frm.doc.tax_rate||0)/100;
  var inr=val*(frm.doc.exchange_rate||0);
  if((frm.doc.invoice_value||0)!==val) frm.set_value('invoice_value', val);
  if((frm.doc.tax_amount||0)!==tax) frm.set_value('tax_amount', tax);
  if((frm.doc.invoice_total||0)!==(val+tax)) frm.set_value('invoice_total', val+tax);
  if((frm.doc.invoice_value_inr||0)!==inr) frm.set_value('invoice_value_inr', inr);
}

